--
-- Table structure for table `exercises`
--

DROP TABLE IF EXISTS `exercises`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `exercises` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `intake_id` int(10) unsigned DEFAULT NULL,
  `lesson_id` int(10) unsigned DEFAULT NULL,
  `title` varchar(200) NOT NULL,
  `intro` varchar(500) DEFAULT NULL,
  `passage` mediumtext DEFAULT NULL,
  `passage_page` smallint(5) unsigned DEFAULT NULL,
  `passage_title` varchar(200) DEFAULT NULL,
  `source` mediumtext DEFAULT NULL,
  `skill` enum('grammar','reading','vocabulary','mixed') NOT NULL DEFAULT 'grammar',
  `level` varchar(10) DEFAULT NULL,
  `due_on` date DEFAULT NULL,
  `published` tinyint(1) NOT NULL DEFAULT 0,
  `unlock_emails` text DEFAULT NULL,
  `created_by` int(10) unsigned DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `learning_config` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`learning_config`)),
  `module` varchar(16) NOT NULL DEFAULT 'homework',
  `content_key` varchar(120) DEFAULT NULL,
  `available_from` datetime DEFAULT NULL,
  `available_until` datetime DEFAULT NULL,
  `is_required` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  KEY `idx_intake_due` (`intake_id`,`due_on`),
  KEY `idx_lesson` (`lesson_id`),
  KEY `fk_ex_creator` (`created_by`),
  CONSTRAINT `fk_ex_creator` FOREIGN KEY (`created_by`) REFERENCES `admin_users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_ex_intake` FOREIGN KEY (`intake_id`) REFERENCES `intakes` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_ex_lesson` FOREIGN KEY (`lesson_id`) REFERENCES `lessons` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=121 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `exercises`
--

SET @OLD_AUTOCOMMIT=@@AUTOCOMMIT, @@AUTOCOMMIT=0;
LOCK TABLES `exercises` WRITE;
