INSERT INTO `exercises` VALUES
(1,NULL,NULL,'A1 · Kapitel 01 — Personalpronomen + sein / haben','Ergänze die passende Form.',NULL,NULL,NULL,'# A1 · Kapitel 01 — Personalpronomen + sein / haben\n# Ergänze die passende Form.\n\nIch ___ neu hier. (sein)\n= bin\n\nDu ___ einen Bruder. (haben)\n= hast\n\nEr ___ Ingenieur. (sein)\n= ist\n\nWir ___ heute Unterricht. (haben)\n= haben\n\nIhr ___ sehr pünktlich. (sein)\n= seid\n\nSie ___ zwei Kinder. (haben)\n= haben\n','grammar','A1',NULL,0,NULL,NULL,'2026-09-24 09:28:04','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(2,NULL,NULL,'A1 · Kapitel 02 — Präsens: regelmäßige Verben','Ergänze die passende Form.',NULL,NULL,NULL,'# A1 · Kapitel 02 — Präsens: regelmäßige Verben\n# Ergänze die passende Form.\n\nIch ___ in Magdeburg. (wohnen)\n= wohne\n\nDu ___ Deutsch. (lernen)\n= lernst\n\nSara ___ heute. (arbeiten)\n= arbeitet\n\nWir ___ eine Pause. (machen)\n= machen\n\nIhr ___ in Berlin. (wohnen)\n= wohnt\n\nDie Schüler ___ viel. (lernen)\n= lernen\n','grammar','A1',NULL,0,NULL,NULL,'2026-09-24 09:29:54','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(3,NULL,NULL,'A1 · Kapitel 03 — Präsens: unregelmäßige Verben','Ergänze die passende Form.',NULL,NULL,NULL,'# A1 · Kapitel 03 — Präsens: unregelmäßige Verben\n# Ergänze die passende Form.\n\nDu ___ sehr gut Deutsch. (sprechen)\n= sprichst\n\nEr ___ nach Berlin. (fahren)\n= fährt\n\nMia ___ ein Buch. (lesen)\n= liest\n\nDu ___ mir bitte. (helfen)\n= hilfst\n\nEr ___ Pizza. (essen)\n= isst\n\nDu ___ lange. (schlafen)\n= schläfst\n','grammar','A1',NULL,0,NULL,NULL,'2026-09-24 09:44:53','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(4,NULL,NULL,'A1 · Kapitel 05 — Nomen, Artikel und Plural','Ergänze die passende Form.',NULL,NULL,NULL,'# A1 · Kapitel 05 — Nomen, Artikel und Plural\n# Ergänze die passende Form.\n\n___ Tisch (bestimmt)\n= der\n\n___ Lampe (unbestimmt)\n= eine\n\n___ Kind (bestimmt)\n= das\n\n___ Bücher (bestimmt, Pl.)\n= die\n\n___ Wohnung (unbestimmt)\n= eine\n\n___ Auto (unbestimmt)\n= ein\n','grammar','A1',NULL,0,NULL,NULL,'2026-09-24 09:44:53','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(5,NULL,NULL,'A1 · Kapitel 06 — Negation: nicht oder kein?','Ergänze die passende Form.',NULL,NULL,NULL,'# A1 · Kapitel 06 — Negation: nicht oder kein?\n# Ergänze die passende Form.\n\nIch habe ___ Zeit.\n= keine\n\nDas ist ___ teuer.\n= nicht\n\nWir trinken ___ Kaffee.\n= keinen\n\nEr kommt heute ___.\n= nicht\n\nSie hat ___ Schwester.\n= keine\n\nDer Bus ist ___ pünktlich.\n= nicht\n','grammar','A1',NULL,0,NULL,NULL,'2026-09-24 09:44:53','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(6,NULL,NULL,'A1 · Kapitel 07 — Akkusativ','Ergänze die passende Form.',NULL,NULL,NULL,'# A1 · Kapitel 07 — Akkusativ\n# Ergänze die passende Form.\n\nIch brauche ___ Stift. (ein)\n= einen\n\nSie kauft ___ Tasche. (die)\n= die\n\nWir sehen ___ Film. (der)\n= den\n\nEr nimmt ___ Buch. (das)\n= das\n\nDu hast ___ Termin. (kein)\n= keinen\n\nIch besuche ___ Eltern. (mein)\n= meine\n','grammar','A1',NULL,0,NULL,NULL,'2026-09-24 09:44:53','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(7,NULL,NULL,'A1 · Kapitel 08 — Possessivartikel','Ergänze die passende Form.',NULL,NULL,NULL,'# A1 · Kapitel 08 — Possessivartikel\n# Ergänze die passende Form.\n\nDas ist ___ Buch. (ich)\n= mein\n\nWo ist ___ Tasche? (du)\n= deine\n\nEr besucht ___ Mutter. (er)\n= seine\n\nWir treffen ___ Freunde. (wir)\n= unsere\n\nHabt ihr ___ Tickets? (ihr)\n= eure\n\nWie ist ___ Adresse? (Sie)\n= Ihre\n','grammar','A1',NULL,0,NULL,NULL,'2026-09-24 09:44:53','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(8,NULL,NULL,'A1 · Kapitel 09 — Modalverben','Ergänze die passende Form.',NULL,NULL,NULL,'# A1 · Kapitel 09 — Modalverben\n# Ergänze die passende Form.\n\nIch ___ schwimmen. (können)\n= kann\n\nDu ___ heute lernen. (müssen)\n= musst\n\nEr ___ Arzt werden. (wollen)\n= will\n\nWir ___ hier nicht rauchen. (dürfen)\n= dürfen\n\nIhr ___ pünktlich sein. (sollen)\n= sollt\n\nSie ___ einen Tee. (möchten)\n= möchten\n','grammar','A1',NULL,0,NULL,NULL,'2026-09-24 09:44:53','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(9,NULL,NULL,'A1 · Kapitel 10 — Trennbare Verben + Imperativ','Ergänze die passende Form.',NULL,NULL,NULL,'# A1 · Kapitel 10 — Trennbare Verben + Imperativ\n# Ergänze die passende Form.\n\nIch ___ um 6 Uhr ___. (aufstehen)\n= stehe\n= auf\n\nDu ___ deine Mutter ___. (anrufen)\n= rufst\n= an\n\nWir ___ heute ___. (einkaufen)\n= kaufen\n= ein\n\nImperativ du: ___ die Tür! (öffnen)\n= Öffne\n\nImperativ ihr: ___ leise! (sein)\n= Seid\n\nImperativ Sie: ___ Sie hier! (warten)\n= Warten\n','grammar','A1',NULL,0,NULL,NULL,'2026-09-24 09:44:53','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(10,NULL,NULL,'A1 · Kapitel 11 — Perfekt: Einstieg','Ergänze die passende Form.',NULL,NULL,NULL,'# A1 · Kapitel 11 — Perfekt: Einstieg\n# Ergänze die passende Form.\n\nIch ___ Deutsch gelernt.\n= habe\n\nWir ___ nach Berlin gefahren.\n= sind\n\nSie ___ Pizza gegessen.\n= hat\n\nEr ___ spät gekommen.\n= ist\n\nDu ___ viel gearbeitet.\n= hast\n\nIhr ___ zu Hause geblieben.\n= seid\n','grammar','A1',NULL,0,NULL,NULL,'2026-09-24 09:44:53','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(11,NULL,NULL,'A1 · Kapitel 12 — Dativ + wichtige Präpositionen','Ergänze die passende Form.',NULL,NULL,NULL,'# A1 · Kapitel 12 — Dativ + wichtige Präpositionen\n# Ergänze die passende Form.\n\nIch fahre mit ___ Bus. (der)\n= dem\n\nSie ist bei ___ Ärztin. (die)\n= der\n\nWir kommen aus ___ Schweiz. (die)\n= der\n\nEr geht zu ___ Arzt. (ein)\n= einem\n\nIch spreche mit ___ Freunden. (mein)\n= meinen\n\nSie hilft ___ Kind. (das)\n= dem\n','grammar','A1',NULL,0,NULL,NULL,'2026-09-24 09:44:53','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(12,NULL,NULL,'A2 · Kapitel 13 — Wechselpräpositionen','Ergänze die passende Form.',NULL,NULL,NULL,'# A2 · Kapitel 13 — Wechselpräpositionen\n# Ergänze die passende Form.\n\nDas Buch liegt auf ___ Tisch. (der)\n= dem\n\nIch lege das Buch auf ___ Tisch. (der)\n= den\n\nWir sitzen in ___ Küche. (die)\n= der\n\nWir gehen in ___ Küche. (die)\n= die\n\nDas Auto steht vor ___ Haus. (das)\n= dem\n\nStell das Fahrrad vor ___ Haus. (das)\n= das\n','grammar','A2',NULL,0,NULL,NULL,'2026-09-24 09:44:53','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(13,NULL,NULL,'A2 · Kapitel 14 — Personalpronomen im Akkusativ / Dativ','Ergänze die passende Form.',NULL,NULL,NULL,'# A2 · Kapitel 14 — Personalpronomen im Akkusativ / Dativ\n# Ergänze die passende Form.\n\nKannst du ___ helfen? (ich)\n= mir\n\nIch sehe ___ morgen. (du)\n= dich\n\nWir besuchen ___. (er)\n= ihn\n\nSie schreibt ___ eine E-Mail. (wir)\n= uns\n\nIch danke ___. (Sie)\n= Ihnen\n\nDer Lehrer erklärt ___ die Aufgabe. (sie, Pl.)\n= ihnen\n','grammar','A2',NULL,0,NULL,NULL,'2026-09-24 09:44:53','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(14,NULL,NULL,'A2 · Kapitel 15 — Verben mit Dativ und Akkusativ','Ergänze die passende Form.',NULL,NULL,NULL,'# A2 · Kapitel 15 — Verben mit Dativ und Akkusativ\n# Ergänze die passende Form.\n\nIch schenke ___ Mutter ___ Blumen. (meine / die)\n= meiner\n= die\n\nEr zeigt ___ Kindern ___ Foto. (die / ein)\n= den\n= ein\n\nWir schicken ___ Chef ___ E-Mail. (unser / eine)\n= unserem\n= eine\n\nSie erklärt ___ Schülern ___ Regel. (die / die)\n= den\n= die\n\nIch bringe ___ Nachbarin ___ Paket. (meine / das)\n= meiner\n= das\n\nDu gibst ___ Freund ___ Schlüssel. (dein / der)\n= deinem\n= den\n','grammar','A2',NULL,0,NULL,NULL,'2026-09-24 09:44:53','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(15,NULL,NULL,'A2 · Kapitel 16 — Reflexive Verben','Ergänze die passende Form.',NULL,NULL,NULL,'# A2 · Kapitel 16 — Reflexive Verben\n# Ergänze die passende Form.\n\nIch ___ ___ für Musik. (interessieren)\n= interessiere\n= mich\n\nDu ___ ___ auf Freitag. (freuen)\n= freust\n= dich\n\nEr ___ ___ mit Freunden. (treffen)\n= trifft\n= sich\n\nWir ___ ___ beeilen. (müssen)\n= müssen\n= uns\n\nIhr ___ ___ an den Termin. (erinnern)\n= erinnert\n= euch\n\nSie ___ ___ die Hände. (waschen)\n= wäscht\n= sich\n','grammar','A2',NULL,0,NULL,NULL,'2026-09-24 09:44:53','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(16,NULL,NULL,'A2 · Kapitel 17 — Perfekt: sicher anwenden','Ergänze die passende Form.',NULL,NULL,NULL,'# A2 · Kapitel 17 — Perfekt: sicher anwenden\n# Ergänze die passende Form.\n\nanrufen → ___\n= angerufen\n\nbesuchen → ___\n= besucht\n\nstudieren → ___\n= studiert\n\nmitbringen → ___\n= mitgebracht\n\nverstehen → ___\n= verstanden\n\ntelefonieren → ___\n= telefoniert\n','grammar','A2',NULL,0,NULL,NULL,'2026-09-24 09:44:53','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(17,NULL,NULL,'A2 · Kapitel 18 — Präteritum: sein, haben, Modalverben','Ergänze die passende Form.',NULL,NULL,NULL,'# A2 · Kapitel 18 — Präteritum: sein, haben, Modalverben\n# Ergänze die passende Form.\n\nGestern ___ ich müde. (sein)\n= war\n\nWir ___ keine Zeit. (haben)\n= hatten\n\nSie ___ früher gehen. (müssen)\n= musste\n\nIch ___ nicht kommen. (können)\n= konnte\n\nEr ___ Arzt werden. (wollen)\n= wollte\n\nIhr ___ dort nicht parken. (dürfen)\n= durftet\n','grammar','A2',NULL,0,NULL,NULL,'2026-09-24 09:44:53','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(18,NULL,NULL,'A2 · Kapitel 19 — Adjektivdeklination: Basis','Ergänze die passende Form.',NULL,NULL,NULL,'# A2 · Kapitel 19 — Adjektivdeklination: Basis\n# Ergänze die passende Form.\n\nder ___ Kurs (intensiv)\n= intensive\n\neine ___ Wohnung (hell)\n= helle\n\nein ___ Auto (neu)\n= neues\n\ndie ___ Bücher (deutsch)\n= deutschen\n\neinen ___ Kaffee (heiß)\n= heißen\n\nmit einem ___ Freund (gut)\n= guten\n','grammar','A2',NULL,0,NULL,NULL,'2026-09-24 09:44:53','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(19,NULL,NULL,'A2 · Kapitel 20 — Komparativ und Superlativ','Ergänze die passende Form.',NULL,NULL,NULL,'# A2 · Kapitel 20 — Komparativ und Superlativ\n# Ergänze die passende Form.\n\nschnell → ___ / ___\n= schneller\n= am schnellsten\n\ngut → ___ / ___\n= besser\n= am besten\n\nteuer → ___ / ___\n= teurer\n= am teuersten\n\ngroß → ___ / ___\n= größer\n= am größten\n\ngern → ___ / ___\n= lieber\n= am liebsten\n\nviel → ___ / ___\n= mehr\n= am meisten\n','grammar','A2',NULL,0,NULL,NULL,'2026-09-24 09:44:53','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(20,NULL,NULL,'A2 · Kapitel 21 — Nebensätze: weil, dass, wenn','Ergänze die passende Form.',NULL,NULL,NULL,'# A2 · Kapitel 21 — Nebensätze: weil, dass, wenn\n# Ergänze die passende Form.\n\nIch lerne Deutsch, weil ich in Deutschland ___. (leben)\n= lebe\n\nSie sagt, dass sie morgen ___. (kommen)\n= kommt\n\nWenn ich Zeit ___, rufe ich dich an. (haben)\n= habe\n\nWir gehen raus, wenn das Wetter gut ___. (sein)\n= ist\n\nEr bleibt zu Hause, weil er arbeiten ___. (müssen)\n= muss\n\nIch glaube, dass der Kurs interessant ___. (sein)\n= ist\n','grammar','A2',NULL,0,NULL,NULL,'2026-09-24 09:44:53','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(21,NULL,NULL,'A2 · Kapitel 22 — Infinitiv mit zu / um … zu','Ergänze die passende Form.',NULL,NULL,NULL,'# A2 · Kapitel 22 — Infinitiv mit zu / um … zu\n# Ergänze die passende Form.\n\nIch versuche, früher ___. (kommen)\n= zu kommen\n\nEr hat vergessen, mich ___. (anrufen)\n= anzurufen\n\nWir lernen, besser Deutsch ___. (sprechen)\n= zu sprechen\n\nSie fährt nach Berlin, um ihre Freundin ___. (besuchen)\n= zu besuchen\n\nIch spare Geld, um ein Auto ___. (kaufen)\n= zu kaufen\n\nEr geht früh schlafen, um morgen fit ___. (sein)\n= zu sein\n','grammar','A2',NULL,0,NULL,NULL,'2026-09-24 09:44:53','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(22,NULL,NULL,'A2 · Kapitel 23 — Relativsätze: Nominativ / Akkusativ','Ergänze die passende Form.',NULL,NULL,NULL,'# A2 · Kapitel 23 — Relativsätze: Nominativ / Akkusativ\n# Ergänze die passende Form.\n\nDas ist die Frau, ___ in Berlin wohnt.\n= die\n\nDas ist der Mann, ___ ich gestern gesehen habe.\n= den\n\nDas ist das Buch, ___ sehr interessant ist.\n= das\n\nDas sind die Leute, ___ wir eingeladen haben.\n= die\n\nIch suche eine Wohnung, ___ einen Balkon hat.\n= die\n\nKennst du den Kurs, ___ ich meine?\n= den\n','grammar','A2',NULL,0,NULL,NULL,'2026-09-24 09:44:53','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(23,NULL,NULL,'A2 · Kapitel 24 — Verben mit Präpositionen + da-/wo-','Ergänze die passende Form.',NULL,NULL,NULL,'# A2 · Kapitel 24 — Verben mit Präpositionen + da-/wo-\n# Ergänze die passende Form.\n\nIch warte ___ den Bus.\n= auf\n\nSie denkt ___ ihre Prüfung.\n= an\n\nWir sprechen ___ das Problem.\n= über\n\nEr interessiert sich ___ Musik.\n= für\n\nWor___ freust du dich?\n= auf\n\nIch freue mich dar___ .\n= auf\n','grammar','A2',NULL,0,NULL,NULL,'2026-09-24 09:44:53','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(24,NULL,NULL,'A2 · Kapitel 25 — Indirekte Fragen','Ergänze die passende Form.',NULL,NULL,NULL,'# A2 · Kapitel 25 — Indirekte Fragen\n# Ergänze die passende Form.\n\nIch weiß nicht, ___ sie heute kommt.\n= ob\n\nKannst du sagen, wann der Zug ___? (fahren)\n= fährt\n\nWeißt du, wo er ___? (wohnen)\n= wohnt\n\nIch frage mich, ___ das richtig ist.\n= ob\n\nSag mir bitte, warum du nicht ___! (kommen)\n= kommst\n\nWissen Sie, wie viel das ___? (kosten)\n= kostet\n','grammar','A2',NULL,0,NULL,NULL,'2026-09-24 09:44:53','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(25,NULL,NULL,'B1 · Kapitel 26 — Adjektivdeklination: System','Ergänze die passende Form.',NULL,NULL,NULL,'# B1 · Kapitel 26 — Adjektivdeklination: System\n# Ergänze die passende Form.\n\nmit dem ___ Chef (neu)\n= neuen\n\nfür einen ___ Kurs (intensiv)\n= intensiven\n\nohne ___ Hilfe (professionell)\n= professionelle\n\nwegen des ___ Wetters (schlecht)\n= schlechten\n\neine ___ Entscheidung (wichtig)\n= wichtige\n\nmit meinen ___ Kollegen (nett)\n= netten\n','grammar','B1',NULL,0,NULL,NULL,'2026-09-24 09:44:53','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(26,NULL,NULL,'B1 · Kapitel 27 — Genitiv + wegen / trotz','Ergänze die passende Form.',NULL,NULL,NULL,'# B1 · Kapitel 27 — Genitiv + wegen / trotz\n# Ergänze die passende Form.\n\ndas Ende ___ Films (der)\n= des\n\ndie Adresse ___ Firma (die)\n= der\n\nwegen ___ Regens (der)\n= des\n\ntrotz ___ Verspätung (die)\n= der\n\ndie Meinung ___ Kollegen (mein)\n= meines\n\nder Name ___ Kindes (das)\n= des\n','grammar','B1',NULL,0,NULL,NULL,'2026-09-24 09:44:53','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(27,NULL,NULL,'B1 · Kapitel 28 — Relativsätze: Dativ + Präposition','Ergänze die passende Form.',NULL,NULL,NULL,'# B1 · Kapitel 28 — Relativsätze: Dativ + Präposition\n# Ergänze die passende Form.\n\nDas ist der Kollege, ___ ich danke.\n= dem\n\nDas ist die Frau, mit ___ ich telefoniere.\n= der\n\nDas sind die Freunde, bei ___ wir wohnen.\n= denen\n\nDas ist das Projekt, an ___ ich arbeite.\n= dem\n\nDie Firma, für ___ er arbeitet, ist groß.\n= die\n\nDer Kurs, von ___ ich erzähle, war gut.\n= dem\n','grammar','B1',NULL,0,NULL,NULL,'2026-09-24 09:44:53','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(28,NULL,NULL,'B1 · Kapitel 29 — Passiv Präsens','Ergänze die passende Form.',NULL,NULL,NULL,'# B1 · Kapitel 29 — Passiv Präsens\n# Ergänze die passende Form.\n\nDie Briefe ___ heute ___. (schicken)\n= werden\n= geschickt\n\nDas Essen ___ frisch ___. (kochen)\n= wird\n= gekocht\n\nHier ___ viel Deutsch ___. (sprechen)\n= wird\n= gesprochen\n\nDie Straße ___ ___. (reparieren)\n= wird\n= repariert\n\nNeue Mitarbeiter ___ ___. (suchen)\n= werden\n= gesucht\n\nDie Rechnung ___ online ___. (bezahlen)\n= wird\n= bezahlt\n','grammar','B1',NULL,0,NULL,NULL,'2026-09-24 09:44:53','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(29,NULL,NULL,'B1 · Kapitel 30 — Passiv Vergangenheit + Modalverb','Ergänze die passende Form.',NULL,NULL,NULL,'# B1 · Kapitel 30 — Passiv Vergangenheit + Modalverb\n# Ergänze die passende Form.\n\nDie Brücke ___ gestern ___. (sperren, Prät.)\n= wurde\n= gesperrt\n\nDie Pakete ___ gestern ___. (liefern, Prät.)\n= wurden\n= geliefert\n\nDer Termin ist ___. (verschieben, Perf.)\n= verschoben worden\n\nDie Dokumente sind ___. (prüfen, Perf.)\n= geprüft worden\n\nDie Aufgabe muss heute ___. (erledigen)\n= erledigt werden\n\nDas Problem kann schnell ___. (lösen)\n= gelöst werden\n','grammar','B1',NULL,0,NULL,NULL,'2026-09-24 09:44:53','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(30,NULL,NULL,'B1 · Kapitel 31 — Konjunktiv II: höflich + Wünsche','Ergänze die passende Form.',NULL,NULL,NULL,'# B1 · Kapitel 31 — Konjunktiv II: höflich + Wünsche\n# Ergänze die passende Form.\n\n___ Sie mir bitte helfen? (können)\n= Könnten|könnten\n\nIch ___ gern mehr Zeit. (haben)\n= hätte\n\nWir ___ gern am Meer. (sein)\n= wären\n\nIch ___ gern in Berlin arbeiten. (werden)\n= würde\n\nDu ___ mehr schlafen. (sollen)\n= solltest\n\n___ ich hier kurz warten? (dürfen)\n= Dürfte|dürfte\n','grammar','B1',NULL,0,NULL,NULL,'2026-09-24 09:44:53','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(31,NULL,NULL,'B1 · Kapitel 32 — Konjunktiv II: irreale Bedingungen','Ergänze die passende Form.',NULL,NULL,NULL,'# B1 · Kapitel 32 — Konjunktiv II: irreale Bedingungen\n# Ergänze die passende Form.\n\nWenn ich reich ___, ___ ich weniger arbeiten. (sein / werden)\n= wäre\n= würde\n\nWenn wir Zeit ___, ___ wir kommen. (haben / können)\n= hätten\n= könnten\n\nWenn er Deutsch ___, ___ er die Stelle bekommen. (sprechen / können)\n= sprechen würde\n= könnte\n\nWenn du früher ___, ___ du den Zug erreichen. (kommen / können)\n= kommen würdest\n= könntest\n\nWenn ich ein Auto ___, ___ ich öfter reisen. (haben / werden)\n= hätte\n= würde\n\nWenn sie hier ___, ___ sie uns helfen. (sein / können)\n= wäre\n= könnte\n','grammar','B1',NULL,0,NULL,NULL,'2026-09-24 09:44:53','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(32,NULL,NULL,'B1 · Kapitel 33 — Plusquamperfekt + nachdem','Ergänze die passende Form.',NULL,NULL,NULL,'# B1 · Kapitel 33 — Plusquamperfekt + nachdem\n# Ergänze die passende Form.\n\nIch ___ schon ___. (essen)\n= hatte\n= gegessen\n\nWir ___ bereits ___. (ankommen)\n= waren\n= angekommen\n\nEr ___ die E-Mail ___. (schreiben)\n= hatte\n= geschrieben\n\nSie ___ nach Hause ___. (fahren)\n= war\n= gefahren\n\nNachdem wir ___ ___, gingen wir los. (frühstücken)\n= gefrühstückt\n= hatten\n\nNachdem er ___ ___, rief er an. (ankommen)\n= angekommen\n= war\n','grammar','B1',NULL,0,NULL,NULL,'2026-09-24 09:44:53','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(33,NULL,NULL,'B1 · Kapitel 34 — Futur I + Vermutungen','Ergänze die passende Form.',NULL,NULL,NULL,'# B1 · Kapitel 34 — Futur I + Vermutungen\n# Ergänze die passende Form.\n\nIch ___ morgen ___. (arbeiten)\n= werde\n= arbeiten\n\nWir ___ nächstes Jahr ___. (umziehen)\n= werden\n= umziehen\n\nSie ___ später ___. (anrufen)\n= wird\n= anrufen\n\nEr ___ wohl zu Hause ___. (sein)\n= wird\n= sein\n\nDas ___ wahrscheinlich lange ___. (dauern)\n= wird\n= dauern\n\nIhr ___ das schon ___. (schaffen)\n= werdet\n= schaffen\n','grammar','B1',NULL,0,NULL,NULL,'2026-09-24 09:44:53','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(34,NULL,NULL,'B1 · Kapitel 35 — Temporale Konnektoren','Ergänze die passende Form.',NULL,NULL,NULL,'# B1 · Kapitel 35 — Temporale Konnektoren\n# Ergänze die passende Form.\n\n___ ich gestern nach Hause kam, war es spät.\n= Als|als\n\n___ ich Zeit habe, gehe ich joggen.\n= Wenn|wenn\n\nIch rufe dich an, ___ ich losfahre.\n= bevor\n\n___ wir gegessen hatten, gingen wir raus.\n= Nachdem|nachdem\n\n___ ich in Deutschland lebe, lerne ich Deutsch.\n= Seitdem|seitdem\n\n___ er arbeitet, hört er Musik.\n= Während|während\n','grammar','B1',NULL,0,NULL,NULL,'2026-09-24 09:44:53','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(35,NULL,NULL,'B1 · Kapitel 36 — Konzessiv + Folge: obwohl / trotzdem / deshalb','Ergänze die passende Form.',NULL,NULL,NULL,'# B1 · Kapitel 36 — Konzessiv + Folge: obwohl / trotzdem / deshalb\n# Ergänze die passende Form.\n\n___ er müde ist, arbeitet er weiter.\n= Obwohl|obwohl\n\nEr ist müde. ___ arbeitet er weiter.\n= Trotzdem\n\nDer Bus fällt aus. ___ nehme ich die Bahn.\n= Deshalb\n\n___ der Kurs schwer ist, macht er Spaß.\n= Obwohl|obwohl\n\nIch bin krank. ___ bleibe ich zu Hause.\n= Deshalb\n\n___ sie wenig Zeit hat, hilft sie uns.\n= Obwohl|obwohl\n','grammar','B1',NULL,0,NULL,NULL,'2026-09-24 09:44:53','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(36,NULL,NULL,'B1 · Kapitel 37 — Zweck und Alternative: damit / um … zu / ohne … zu / statt … zu','Ergänze die passende Form.',NULL,NULL,NULL,'# B1 · Kapitel 37 — Zweck und Alternative: damit / um … zu / ohne … zu / statt … zu\n# Ergänze die passende Form.\n\nIch schreibe es auf, ___ ich es nicht vergesse.\n= damit\n\nEr spart Geld, ___ ein Auto zu kaufen.\n= um\n\nSie ging, ___ sich zu verabschieden.\n= ohne\n\nEr spielt, ___ zu lernen.\n= statt\n\nIch erkläre es noch einmal, ___ alle es verstehen.\n= damit\n\nWir fahren früh los, ___ keinen Stau zu haben.\n= um\n','grammar','B1',NULL,0,NULL,NULL,'2026-09-24 09:44:53','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(37,NULL,NULL,'B1 · Kapitel 38 — N-Deklination','Ergänze die passende Form.',NULL,NULL,NULL,'# B1 · Kapitel 38 — N-Deklination\n# Ergänze die passende Form.\n\nIch sehe den ___. (Kunde)\n= Kunden\n\nIch spreche mit dem ___. (Kollege)\n= Kollegen\n\nDas ist das Buch des ___. (Student)\n= Studenten\n\nWir helfen dem ___. (Mensch)\n= Menschen\n\nIch treffe Herrn ___. (Name: Weber)\n= Weber\n\nDie Meinung des ___ ist wichtig. (Experte)\n= Experten\n','grammar','B1',NULL,0,NULL,NULL,'2026-09-24 09:44:53','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(38,NULL,NULL,'B1 · Kapitel 39 — lassen + Infinitiv','Ergänze die passende Form.',NULL,NULL,NULL,'# B1 · Kapitel 39 — lassen + Infinitiv\n# Ergänze die passende Form.\n\nIch ___ mein Fahrrad reparieren.\n= lasse\n\nWir ___ die Wohnung streichen.\n= lassen\n\nSie ___ ihre Fotos drucken.\n= lässt\n\n___ mich bitte erklären!\n= Lass|lass\n\nEr ___ sein Auto waschen.\n= lässt\n\nDie Eltern ___ die Kinder draußen spielen.\n= lassen\n','grammar','B1',NULL,0,NULL,NULL,'2026-09-24 09:44:53','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(39,NULL,NULL,'B1 · Kapitel 41 — Nominalisierung + zu-Infinitiv als Nomen','Ergänze die passende Form.',NULL,NULL,NULL,'# B1 · Kapitel 41 — Nominalisierung + zu-Infinitiv als Nomen\n# Ergänze die passende Form.\n\n___ macht mir Spaß. (kochen)\n= Kochen\n\nBeim ___ höre ich Musik. (lernen)\n= Lernen\n\nZum ___ brauche ich einen Laptop. (arbeiten)\n= Arbeiten\n\nNach dem ___ gehe ich spazieren. (essen)\n= Essen\n\n___ ist hier verboten. (rauchen)\n= Rauchen\n\nVor dem ___ trinke ich Kaffee. (fahren)\n= Fahren\n','grammar','B1',NULL,0,NULL,NULL,'2026-09-24 09:44:53','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(40,NULL,NULL,'B1 · Kapitel 42 — Partizipien als Adjektive','Ergänze die passende Form.',NULL,NULL,NULL,'# B1 · Kapitel 42 — Partizipien als Adjektive\n# Ergänze die passende Form.\n\ndas ___ Kind (lachen)\n= lachende\n\ndie ___ Tür (schließen)\n= geschlossene\n\nder ___ Bus (ankommen)\n= ankommende\n\ndie ___ E-Mail (schreiben)\n= geschriebene\n\ndie ___ Studenten (lernen)\n= lernenden\n\ndas ___ Fahrrad (reparieren)\n= reparierte\n','grammar','B1',NULL,0,NULL,NULL,'2026-09-24 09:44:53','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(41,NULL,NULL,'B1 · Kapitel 43 — Gesamtwiederholung: Satzverknüpfung','Ergänze die passende Form.',NULL,NULL,NULL,'# B1 · Kapitel 43 — Gesamtwiederholung: Satzverknüpfung\n# Ergänze die passende Form.\n\nIch bleibe zu Hause, ___ ich krank bin.\n= weil\n\n___ es regnet, gehen wir spazieren.\n= Obwohl|obwohl\n\nIch spreche langsam, ___ du mich verstehst.\n= damit\n\nDas ist der Mann, ___ mir geholfen hat.\n= der\n\n___ ich Zeit habe, besuche ich dich.\n= Wenn|wenn\n\nDer Zug hat Verspätung. ___ komme ich später.\n= Deshalb\n','grammar','B1',NULL,0,NULL,NULL,'2026-09-24 09:44:53','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(42,3,NULL,'A1 · Kapitel 01 — Personalpronomen + sein / haben','Ergänze die passende Form.',NULL,NULL,NULL,'# A1 · Kapitel 01 — Personalpronomen + sein / haben\n# Ergänze die passende Form.\n\nIch ___ neu hier. (sein)\n= bin\n\nDu ___ einen Bruder. (haben)\n= hast\n\nEr ___ Ingenieur. (sein)\n= ist\n\nWir ___ heute Unterricht. (haben)\n= haben\n\nIhr ___ sehr pünktlich. (sein)\n= seid\n\nSie ___ zwei Kinder. (haben)\n= haben\n','grammar','A1',NULL,1,NULL,NULL,'2026-09-24 14:54:55','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(43,3,NULL,'A1 · Kapitel 02 — Präsens: regelmäßige Verben','Ergänze die passende Form.',NULL,NULL,NULL,'# A1 · Kapitel 02 — Präsens: regelmäßige Verben\n# Ergänze die passende Form.\n\nIch ___ in Magdeburg. (wohnen)\n= wohne\n\nDu ___ Deutsch. (lernen)\n= lernst\n\nSara ___ heute. (arbeiten)\n= arbeitet\n\nWir ___ eine Pause. (machen)\n= machen\n\nIhr ___ in Berlin. (wohnen)\n= wohnt\n\nDie Schüler ___ viel. (lernen)\n= lernen\n','grammar','A1',NULL,1,NULL,NULL,'2026-09-24 14:54:55','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(44,3,NULL,'A1 · Kapitel 03 — Präsens: unregelmäßige Verben','Ergänze die passende Form.',NULL,NULL,NULL,'# A1 · Kapitel 03 — Präsens: unregelmäßige Verben\n# Ergänze die passende Form.\n\nDu ___ sehr gut Deutsch. (sprechen)\n= sprichst\n\nEr ___ nach Berlin. (fahren)\n= fährt\n\nMia ___ ein Buch. (lesen)\n= liest\n\nDu ___ mir bitte. (helfen)\n= hilfst\n\nEr ___ Pizza. (essen)\n= isst\n\nDu ___ lange. (schlafen)\n= schläfst\n','grammar','A1',NULL,1,NULL,NULL,'2026-09-24 14:54:55','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(45,3,NULL,'A1 · Kapitel 05 — Nomen, Artikel und Plural','Ergänze die passende Form.',NULL,NULL,NULL,'# A1 · Kapitel 05 — Nomen, Artikel und Plural\n# Ergänze die passende Form.\n\n___ Tisch (bestimmt)\n= der\n\n___ Lampe (unbestimmt)\n= eine\n\n___ Kind (bestimmt)\n= das\n\n___ Bücher (bestimmt, Pl.)\n= die\n\n___ Wohnung (unbestimmt)\n= eine\n\n___ Auto (unbestimmt)\n= ein\n','grammar','A1',NULL,1,NULL,NULL,'2026-09-24 14:54:55','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(46,3,NULL,'A1 · Kapitel 06 — Negation: nicht oder kein?','Ergänze die passende Form.',NULL,NULL,NULL,'# A1 · Kapitel 06 — Negation: nicht oder kein?\n# Ergänze die passende Form.\n\nIch habe ___ Zeit.\n= keine\n\nDas ist ___ teuer.\n= nicht\n\nWir trinken ___ Kaffee.\n= keinen\n\nEr kommt heute ___.\n= nicht\n\nSie hat ___ Schwester.\n= keine\n\nDer Bus ist ___ pünktlich.\n= nicht\n','grammar','A1',NULL,1,NULL,NULL,'2026-09-24 14:54:55','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(47,3,NULL,'A1 · Kapitel 07 — Akkusativ','Ergänze die passende Form.',NULL,NULL,NULL,'# A1 · Kapitel 07 — Akkusativ\n# Ergänze die passende Form.\n\nIch brauche ___ Stift. (ein)\n= einen\n\nSie kauft ___ Tasche. (die)\n= die\n\nWir sehen ___ Film. (der)\n= den\n\nEr nimmt ___ Buch. (das)\n= das\n\nDu hast ___ Termin. (kein)\n= keinen\n\nIch besuche ___ Eltern. (mein)\n= meine\n','grammar','A1',NULL,1,NULL,NULL,'2026-09-24 14:54:55','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(48,3,NULL,'A1 · Kapitel 08 — Possessivartikel','Ergänze die passende Form.',NULL,NULL,NULL,'# A1 · Kapitel 08 — Possessivartikel\n# Ergänze die passende Form.\n\nDas ist ___ Buch. (ich)\n= mein\n\nWo ist ___ Tasche? (du)\n= deine\n\nEr besucht ___ Mutter. (er)\n= seine\n\nWir treffen ___ Freunde. (wir)\n= unsere\n\nHabt ihr ___ Tickets? (ihr)\n= eure\n\nWie ist ___ Adresse? (Sie)\n= Ihre\n','grammar','A1',NULL,1,NULL,NULL,'2026-09-24 14:54:55','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(49,3,NULL,'A1 · Kapitel 09 — Modalverben','Ergänze die passende Form.',NULL,NULL,NULL,'# A1 · Kapitel 09 — Modalverben\n# Ergänze die passende Form.\n\nIch ___ schwimmen. (können)\n= kann\n\nDu ___ heute lernen. (müssen)\n= musst\n\nEr ___ Arzt werden. (wollen)\n= will\n\nWir ___ hier nicht rauchen. (dürfen)\n= dürfen\n\nIhr ___ pünktlich sein. (sollen)\n= sollt\n\nSie ___ einen Tee. (möchten)\n= möchten\n','grammar','A1',NULL,1,NULL,NULL,'2026-09-24 14:54:55','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(50,3,NULL,'A1 · Kapitel 10 — Trennbare Verben + Imperativ','Ergänze die passende Form.',NULL,NULL,NULL,'# A1 · Kapitel 10 — Trennbare Verben + Imperativ\n# Ergänze die passende Form.\n\nIch ___ um 6 Uhr ___. (aufstehen)\n= stehe\n= auf\n\nDu ___ deine Mutter ___. (anrufen)\n= rufst\n= an\n\nWir ___ heute ___. (einkaufen)\n= kaufen\n= ein\n\nImperativ du: ___ die Tür! (öffnen)\n= Öffne\n\nImperativ ihr: ___ leise! (sein)\n= Seid\n\nImperativ Sie: ___ Sie hier! (warten)\n= Warten\n','grammar','A1',NULL,1,NULL,NULL,'2026-09-24 14:54:55','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(51,3,NULL,'A1 · Kapitel 11 — Perfekt: Einstieg','Ergänze die passende Form.',NULL,NULL,NULL,'# A1 · Kapitel 11 — Perfekt: Einstieg\n# Ergänze die passende Form.\n\nIch ___ Deutsch gelernt.\n= habe\n\nWir ___ nach Berlin gefahren.\n= sind\n\nSie ___ Pizza gegessen.\n= hat\n\nEr ___ spät gekommen.\n= ist\n\nDu ___ viel gearbeitet.\n= hast\n\nIhr ___ zu Hause geblieben.\n= seid\n','grammar','A1',NULL,1,NULL,NULL,'2026-09-24 14:54:55','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(52,3,NULL,'A1 · Kapitel 12 — Dativ + wichtige Präpositionen','Ergänze die passende Form.',NULL,NULL,NULL,'# A1 · Kapitel 12 — Dativ + wichtige Präpositionen\n# Ergänze die passende Form.\n\nIch fahre mit ___ Bus. (der)\n= dem\n\nSie ist bei ___ Ärztin. (die)\n= der\n\nWir kommen aus ___ Schweiz. (die)\n= der\n\nEr geht zu ___ Arzt. (ein)\n= einem\n\nIch spreche mit ___ Freunden. (mein)\n= meinen\n\nSie hilft ___ Kind. (das)\n= dem\n','grammar','A1',NULL,1,NULL,NULL,'2026-09-24 14:54:55','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(53,3,NULL,'A2 · Kapitel 13 — Wechselpräpositionen','Ergänze die passende Form.',NULL,NULL,NULL,'# A2 · Kapitel 13 — Wechselpräpositionen\n# Ergänze die passende Form.\n\nDas Buch liegt auf ___ Tisch. (der)\n= dem\n\nIch lege das Buch auf ___ Tisch. (der)\n= den\n\nWir sitzen in ___ Küche. (die)\n= der\n\nWir gehen in ___ Küche. (die)\n= die\n\nDas Auto steht vor ___ Haus. (das)\n= dem\n\nStell das Fahrrad vor ___ Haus. (das)\n= das\n','grammar','A2',NULL,1,NULL,NULL,'2026-09-24 14:54:55','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(54,3,NULL,'A2 · Kapitel 14 — Personalpronomen im Akkusativ / Dativ','Ergänze die passende Form.',NULL,NULL,NULL,'# A2 · Kapitel 14 — Personalpronomen im Akkusativ / Dativ\n# Ergänze die passende Form.\n\nKannst du ___ helfen? (ich)\n= mir\n\nIch sehe ___ morgen. (du)\n= dich\n\nWir besuchen ___. (er)\n= ihn\n\nSie schreibt ___ eine E-Mail. (wir)\n= uns\n\nIch danke ___. (Sie)\n= Ihnen\n\nDer Lehrer erklärt ___ die Aufgabe. (sie, Pl.)\n= ihnen\n','grammar','A2',NULL,1,NULL,NULL,'2026-09-24 14:54:55','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(55,3,NULL,'A2 · Kapitel 15 — Verben mit Dativ und Akkusativ','Ergänze die passende Form.',NULL,NULL,NULL,'# A2 · Kapitel 15 — Verben mit Dativ und Akkusativ\n# Ergänze die passende Form.\n\nIch schenke ___ Mutter ___ Blumen. (meine / die)\n= meiner\n= die\n\nEr zeigt ___ Kindern ___ Foto. (die / ein)\n= den\n= ein\n\nWir schicken ___ Chef ___ E-Mail. (unser / eine)\n= unserem\n= eine\n\nSie erklärt ___ Schülern ___ Regel. (die / die)\n= den\n= die\n\nIch bringe ___ Nachbarin ___ Paket. (meine / das)\n= meiner\n= das\n\nDu gibst ___ Freund ___ Schlüssel. (dein / der)\n= deinem\n= den\n','grammar','A2',NULL,1,NULL,NULL,'2026-09-24 14:54:55','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(56,3,NULL,'A2 · Kapitel 16 — Reflexive Verben','Ergänze die passende Form.',NULL,NULL,NULL,'# A2 · Kapitel 16 — Reflexive Verben\n# Ergänze die passende Form.\n\nIch ___ ___ für Musik. (interessieren)\n= interessiere\n= mich\n\nDu ___ ___ auf Freitag. (freuen)\n= freust\n= dich\n\nEr ___ ___ mit Freunden. (treffen)\n= trifft\n= sich\n\nWir ___ ___ beeilen. (müssen)\n= müssen\n= uns\n\nIhr ___ ___ an den Termin. (erinnern)\n= erinnert\n= euch\n\nSie ___ ___ die Hände. (waschen)\n= wäscht\n= sich\n','grammar','A2',NULL,1,NULL,NULL,'2026-09-24 14:54:55','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(57,3,NULL,'A2 · Kapitel 17 — Perfekt: sicher anwenden','Ergänze die passende Form.',NULL,NULL,NULL,'# A2 · Kapitel 17 — Perfekt: sicher anwenden\n# Ergänze die passende Form.\n\nanrufen → ___\n= angerufen\n\nbesuchen → ___\n= besucht\n\nstudieren → ___\n= studiert\n\nmitbringen → ___\n= mitgebracht\n\nverstehen → ___\n= verstanden\n\ntelefonieren → ___\n= telefoniert\n','grammar','A2',NULL,1,NULL,NULL,'2026-09-24 14:54:55','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(58,3,NULL,'A2 · Kapitel 18 — Präteritum: sein, haben, Modalverben','Ergänze die passende Form.',NULL,NULL,NULL,'# A2 · Kapitel 18 — Präteritum: sein, haben, Modalverben\n# Ergänze die passende Form.\n\nGestern ___ ich müde. (sein)\n= war\n\nWir ___ keine Zeit. (haben)\n= hatten\n\nSie ___ früher gehen. (müssen)\n= musste\n\nIch ___ nicht kommen. (können)\n= konnte\n\nEr ___ Arzt werden. (wollen)\n= wollte\n\nIhr ___ dort nicht parken. (dürfen)\n= durftet\n','grammar','A2',NULL,1,NULL,NULL,'2026-09-24 14:54:55','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(59,3,NULL,'A2 · Kapitel 19 — Adjektivdeklination: Basis','Ergänze die passende Form.',NULL,NULL,NULL,'# A2 · Kapitel 19 — Adjektivdeklination: Basis\n# Ergänze die passende Form.\n\nder ___ Kurs (intensiv)\n= intensive\n\neine ___ Wohnung (hell)\n= helle\n\nein ___ Auto (neu)\n= neues\n\ndie ___ Bücher (deutsch)\n= deutschen\n\neinen ___ Kaffee (heiß)\n= heißen\n\nmit einem ___ Freund (gut)\n= guten\n','grammar','A2',NULL,1,NULL,NULL,'2026-09-24 14:54:55','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(60,3,NULL,'A2 · Kapitel 20 — Komparativ und Superlativ','Ergänze die passende Form.',NULL,NULL,NULL,'# A2 · Kapitel 20 — Komparativ und Superlativ\n# Ergänze die passende Form.\n\nschnell → ___ / ___\n= schneller\n= am schnellsten\n\ngut → ___ / ___\n= besser\n= am besten\n\nteuer → ___ / ___\n= teurer\n= am teuersten\n\ngroß → ___ / ___\n= größer\n= am größten\n\ngern → ___ / ___\n= lieber\n= am liebsten\n\nviel → ___ / ___\n= mehr\n= am meisten\n','grammar','A2',NULL,1,NULL,NULL,'2026-09-24 14:54:55','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(61,3,NULL,'A2 · Kapitel 21 — Nebensätze: weil, dass, wenn','Ergänze die passende Form.',NULL,NULL,NULL,'# A2 · Kapitel 21 — Nebensätze: weil, dass, wenn\n# Ergänze die passende Form.\n\nIch lerne Deutsch, weil ich in Deutschland ___. (leben)\n= lebe\n\nSie sagt, dass sie morgen ___. (kommen)\n= kommt\n\nWenn ich Zeit ___, rufe ich dich an. (haben)\n= habe\n\nWir gehen raus, wenn das Wetter gut ___. (sein)\n= ist\n\nEr bleibt zu Hause, weil er arbeiten ___. (müssen)\n= muss\n\nIch glaube, dass der Kurs interessant ___. (sein)\n= ist\n','grammar','A2',NULL,1,NULL,NULL,'2026-09-24 14:54:55','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(62,3,NULL,'A2 · Kapitel 22 — Infinitiv mit zu / um … zu','Ergänze die passende Form.',NULL,NULL,NULL,'# A2 · Kapitel 22 — Infinitiv mit zu / um … zu\n# Ergänze die passende Form.\n\nIch versuche, früher ___. (kommen)\n= zu kommen\n\nEr hat vergessen, mich ___. (anrufen)\n= anzurufen\n\nWir lernen, besser Deutsch ___. (sprechen)\n= zu sprechen\n\nSie fährt nach Berlin, um ihre Freundin ___. (besuchen)\n= zu besuchen\n\nIch spare Geld, um ein Auto ___. (kaufen)\n= zu kaufen\n\nEr geht früh schlafen, um morgen fit ___. (sein)\n= zu sein\n','grammar','A2',NULL,1,NULL,NULL,'2026-09-24 14:54:55','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(63,3,NULL,'A2 · Kapitel 23 — Relativsätze: Nominativ / Akkusativ','Ergänze die passende Form.',NULL,NULL,NULL,'# A2 · Kapitel 23 — Relativsätze: Nominativ / Akkusativ\n# Ergänze die passende Form.\n\nDas ist die Frau, ___ in Berlin wohnt.\n= die\n\nDas ist der Mann, ___ ich gestern gesehen habe.\n= den\n\nDas ist das Buch, ___ sehr interessant ist.\n= das\n\nDas sind die Leute, ___ wir eingeladen haben.\n= die\n\nIch suche eine Wohnung, ___ einen Balkon hat.\n= die\n\nKennst du den Kurs, ___ ich meine?\n= den\n','grammar','A2',NULL,1,NULL,NULL,'2026-09-24 14:54:55','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(64,3,NULL,'A2 · Kapitel 24 — Verben mit Präpositionen + da-/wo-','Ergänze die passende Form.',NULL,NULL,NULL,'# A2 · Kapitel 24 — Verben mit Präpositionen + da-/wo-\n# Ergänze die passende Form.\n\nIch warte ___ den Bus.\n= auf\n\nSie denkt ___ ihre Prüfung.\n= an\n\nWir sprechen ___ das Problem.\n= über\n\nEr interessiert sich ___ Musik.\n= für\n\nWor___ freust du dich?\n= auf\n\nIch freue mich dar___ .\n= auf\n','grammar','A2',NULL,1,NULL,NULL,'2026-09-24 14:54:55','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(65,3,NULL,'A2 · Kapitel 25 — Indirekte Fragen','Ergänze die passende Form.',NULL,NULL,NULL,'# A2 · Kapitel 25 — Indirekte Fragen\n# Ergänze die passende Form.\n\nIch weiß nicht, ___ sie heute kommt.\n= ob\n\nKannst du sagen, wann der Zug ___? (fahren)\n= fährt\n\nWeißt du, wo er ___? (wohnen)\n= wohnt\n\nIch frage mich, ___ das richtig ist.\n= ob\n\nSag mir bitte, warum du nicht ___! (kommen)\n= kommst\n\nWissen Sie, wie viel das ___? (kosten)\n= kostet\n','grammar','A2',NULL,1,NULL,NULL,'2026-09-24 14:54:55','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(66,3,NULL,'B1 · Kapitel 26 — Adjektivdeklination: System','Ergänze die passende Form.',NULL,NULL,NULL,'# B1 · Kapitel 26 — Adjektivdeklination: System\n# Ergänze die passende Form.\n\nmit dem ___ Chef (neu)\n= neuen\n\nfür einen ___ Kurs (intensiv)\n= intensiven\n\nohne ___ Hilfe (professionell)\n= professionelle\n\nwegen des ___ Wetters (schlecht)\n= schlechten\n\neine ___ Entscheidung (wichtig)\n= wichtige\n\nmit meinen ___ Kollegen (nett)\n= netten\n','grammar','B1',NULL,1,NULL,NULL,'2026-09-24 14:54:55','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(67,3,NULL,'B1 · Kapitel 27 — Genitiv + wegen / trotz','Ergänze die passende Form.',NULL,NULL,NULL,'# B1 · Kapitel 27 — Genitiv + wegen / trotz\n# Ergänze die passende Form.\n\ndas Ende ___ Films (der)\n= des\n\ndie Adresse ___ Firma (die)\n= der\n\nwegen ___ Regens (der)\n= des\n\ntrotz ___ Verspätung (die)\n= der\n\ndie Meinung ___ Kollegen (mein)\n= meines\n\nder Name ___ Kindes (das)\n= des\n','grammar','B1',NULL,1,NULL,NULL,'2026-09-24 14:54:55','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(68,3,NULL,'B1 · Kapitel 28 — Relativsätze: Dativ + Präposition','Ergänze die passende Form.',NULL,NULL,NULL,'# B1 · Kapitel 28 — Relativsätze: Dativ + Präposition\n# Ergänze die passende Form.\n\nDas ist der Kollege, ___ ich danke.\n= dem\n\nDas ist die Frau, mit ___ ich telefoniere.\n= der\n\nDas sind die Freunde, bei ___ wir wohnen.\n= denen\n\nDas ist das Projekt, an ___ ich arbeite.\n= dem\n\nDie Firma, für ___ er arbeitet, ist groß.\n= die\n\nDer Kurs, von ___ ich erzähle, war gut.\n= dem\n','grammar','B1',NULL,1,NULL,NULL,'2026-09-24 14:54:55','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(69,3,NULL,'B1 · Kapitel 29 — Passiv Präsens','Ergänze die passende Form.',NULL,NULL,NULL,'# B1 · Kapitel 29 — Passiv Präsens\n# Ergänze die passende Form.\n\nDie Briefe ___ heute ___. (schicken)\n= werden\n= geschickt\n\nDas Essen ___ frisch ___. (kochen)\n= wird\n= gekocht\n\nHier ___ viel Deutsch ___. (sprechen)\n= wird\n= gesprochen\n\nDie Straße ___ ___. (reparieren)\n= wird\n= repariert\n\nNeue Mitarbeiter ___ ___. (suchen)\n= werden\n= gesucht\n\nDie Rechnung ___ online ___. (bezahlen)\n= wird\n= bezahlt\n','grammar','B1',NULL,1,NULL,NULL,'2026-09-24 14:54:55','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(70,3,NULL,'B1 · Kapitel 30 — Passiv Vergangenheit + Modalverb','Ergänze die passende Form.',NULL,NULL,NULL,'# B1 · Kapitel 30 — Passiv Vergangenheit + Modalverb\n# Ergänze die passende Form.\n\nDie Brücke ___ gestern ___. (sperren, Prät.)\n= wurde\n= gesperrt\n\nDie Pakete ___ gestern ___. (liefern, Prät.)\n= wurden\n= geliefert\n\nDer Termin ist ___. (verschieben, Perf.)\n= verschoben worden\n\nDie Dokumente sind ___. (prüfen, Perf.)\n= geprüft worden\n\nDie Aufgabe muss heute ___. (erledigen)\n= erledigt werden\n\nDas Problem kann schnell ___. (lösen)\n= gelöst werden\n','grammar','B1',NULL,1,NULL,NULL,'2026-09-24 14:54:55','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(71,3,NULL,'B1 · Kapitel 31 — Konjunktiv II: höflich + Wünsche','Ergänze die passende Form.',NULL,NULL,NULL,'# B1 · Kapitel 31 — Konjunktiv II: höflich + Wünsche\n# Ergänze die passende Form.\n\n___ Sie mir bitte helfen? (können)\n= Könnten|könnten\n\nIch ___ gern mehr Zeit. (haben)\n= hätte\n\nWir ___ gern am Meer. (sein)\n= wären\n\nIch ___ gern in Berlin arbeiten. (werden)\n= würde\n\nDu ___ mehr schlafen. (sollen)\n= solltest\n\n___ ich hier kurz warten? (dürfen)\n= Dürfte|dürfte\n','grammar','B1',NULL,1,NULL,NULL,'2026-09-24 14:54:55','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(72,3,NULL,'B1 · Kapitel 32 — Konjunktiv II: irreale Bedingungen','Ergänze die passende Form.',NULL,NULL,NULL,'# B1 · Kapitel 32 — Konjunktiv II: irreale Bedingungen\n# Ergänze die passende Form.\n\nWenn ich reich ___, ___ ich weniger arbeiten. (sein / werden)\n= wäre\n= würde\n\nWenn wir Zeit ___, ___ wir kommen. (haben / können)\n= hätten\n= könnten\n\nWenn er Deutsch ___, ___ er die Stelle bekommen. (sprechen / können)\n= sprechen würde\n= könnte\n\nWenn du früher ___, ___ du den Zug erreichen. (kommen / können)\n= kommen würdest\n= könntest\n\nWenn ich ein Auto ___, ___ ich öfter reisen. (haben / werden)\n= hätte\n= würde\n\nWenn sie hier ___, ___ sie uns helfen. (sein / können)\n= wäre\n= könnte\n','grammar','B1',NULL,1,NULL,NULL,'2026-09-24 14:54:55','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(73,3,NULL,'B1 · Kapitel 33 — Plusquamperfekt + nachdem','Ergänze die passende Form.',NULL,NULL,NULL,'# B1 · Kapitel 33 — Plusquamperfekt + nachdem\n# Ergänze die passende Form.\n\nIch ___ schon ___. (essen)\n= hatte\n= gegessen\n\nWir ___ bereits ___. (ankommen)\n= waren\n= angekommen\n\nEr ___ die E-Mail ___. (schreiben)\n= hatte\n= geschrieben\n\nSie ___ nach Hause ___. (fahren)\n= war\n= gefahren\n\nNachdem wir ___ ___, gingen wir los. (frühstücken)\n= gefrühstückt\n= hatten\n\nNachdem er ___ ___, rief er an. (ankommen)\n= angekommen\n= war\n','grammar','B1',NULL,1,NULL,NULL,'2026-09-24 14:54:55','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(74,3,NULL,'B1 · Kapitel 34 — Futur I + Vermutungen','Ergänze die passende Form.',NULL,NULL,NULL,'# B1 · Kapitel 34 — Futur I + Vermutungen\n# Ergänze die passende Form.\n\nIch ___ morgen ___. (arbeiten)\n= werde\n= arbeiten\n\nWir ___ nächstes Jahr ___. (umziehen)\n= werden\n= umziehen\n\nSie ___ später ___. (anrufen)\n= wird\n= anrufen\n\nEr ___ wohl zu Hause ___. (sein)\n= wird\n= sein\n\nDas ___ wahrscheinlich lange ___. (dauern)\n= wird\n= dauern\n\nIhr ___ das schon ___. (schaffen)\n= werdet\n= schaffen\n','grammar','B1',NULL,1,NULL,NULL,'2026-09-24 14:54:55','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(75,3,NULL,'B1 · Kapitel 35 — Temporale Konnektoren','Ergänze die passende Form.',NULL,NULL,NULL,'# B1 · Kapitel 35 — Temporale Konnektoren\n# Ergänze die passende Form.\n\n___ ich gestern nach Hause kam, war es spät.\n= Als|als\n\n___ ich Zeit habe, gehe ich joggen.\n= Wenn|wenn\n\nIch rufe dich an, ___ ich losfahre.\n= bevor\n\n___ wir gegessen hatten, gingen wir raus.\n= Nachdem|nachdem\n\n___ ich in Deutschland lebe, lerne ich Deutsch.\n= Seitdem|seitdem\n\n___ er arbeitet, hört er Musik.\n= Während|während\n','grammar','B1',NULL,1,NULL,NULL,'2026-09-24 14:54:55','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(76,3,NULL,'B1 · Kapitel 36 — Konzessiv + Folge: obwohl / trotzdem / deshalb','Ergänze die passende Form.',NULL,NULL,NULL,'# B1 · Kapitel 36 — Konzessiv + Folge: obwohl / trotzdem / deshalb\n# Ergänze die passende Form.\n\n___ er müde ist, arbeitet er weiter.\n= Obwohl|obwohl\n\nEr ist müde. ___ arbeitet er weiter.\n= Trotzdem\n\nDer Bus fällt aus. ___ nehme ich die Bahn.\n= Deshalb\n\n___ der Kurs schwer ist, macht er Spaß.\n= Obwohl|obwohl\n\nIch bin krank. ___ bleibe ich zu Hause.\n= Deshalb\n\n___ sie wenig Zeit hat, hilft sie uns.\n= Obwohl|obwohl\n','grammar','B1',NULL,1,NULL,NULL,'2026-09-24 14:54:55','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(77,3,NULL,'B1 · Kapitel 37 — Zweck und Alternative: damit / um … zu / ohne … zu / statt … zu','Ergänze die passende Form.',NULL,NULL,NULL,'# B1 · Kapitel 37 — Zweck und Alternative: damit / um … zu / ohne … zu / statt … zu\n# Ergänze die passende Form.\n\nIch schreibe es auf, ___ ich es nicht vergesse.\n= damit\n\nEr spart Geld, ___ ein Auto zu kaufen.\n= um\n\nSie ging, ___ sich zu verabschieden.\n= ohne\n\nEr spielt, ___ zu lernen.\n= statt\n\nIch erkläre es noch einmal, ___ alle es verstehen.\n= damit\n\nWir fahren früh los, ___ keinen Stau zu haben.\n= um\n','grammar','B1',NULL,1,NULL,NULL,'2026-09-24 14:54:55','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(78,3,NULL,'B1 · Kapitel 38 — N-Deklination','Ergänze die passende Form.',NULL,NULL,NULL,'# B1 · Kapitel 38 — N-Deklination\n# Ergänze die passende Form.\n\nIch sehe den ___. (Kunde)\n= Kunden\n\nIch spreche mit dem ___. (Kollege)\n= Kollegen\n\nDas ist das Buch des ___. (Student)\n= Studenten\n\nWir helfen dem ___. (Mensch)\n= Menschen\n\nIch treffe Herrn ___. (Name: Weber)\n= Weber\n\nDie Meinung des ___ ist wichtig. (Experte)\n= Experten\n','grammar','B1',NULL,1,NULL,NULL,'2026-09-24 14:54:55','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(79,3,NULL,'B1 · Kapitel 39 — lassen + Infinitiv','Ergänze die passende Form.',NULL,NULL,NULL,'# B1 · Kapitel 39 — lassen + Infinitiv\n# Ergänze die passende Form.\n\nIch ___ mein Fahrrad reparieren.\n= lasse\n\nWir ___ die Wohnung streichen.\n= lassen\n\nSie ___ ihre Fotos drucken.\n= lässt\n\n___ mich bitte erklären!\n= Lass|lass\n\nEr ___ sein Auto waschen.\n= lässt\n\nDie Eltern ___ die Kinder draußen spielen.\n= lassen\n','grammar','B1',NULL,1,NULL,NULL,'2026-09-24 14:54:55','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(80,3,NULL,'B1 · Kapitel 41 — Nominalisierung + zu-Infinitiv als Nomen','Ergänze die passende Form.',NULL,NULL,NULL,'# B1 · Kapitel 41 — Nominalisierung + zu-Infinitiv als Nomen\n# Ergänze die passende Form.\n\n___ macht mir Spaß. (kochen)\n= Kochen\n\nBeim ___ höre ich Musik. (lernen)\n= Lernen\n\nZum ___ brauche ich einen Laptop. (arbeiten)\n= Arbeiten\n\nNach dem ___ gehe ich spazieren. (essen)\n= Essen\n\n___ ist hier verboten. (rauchen)\n= Rauchen\n\nVor dem ___ trinke ich Kaffee. (fahren)\n= Fahren\n','grammar','B1',NULL,1,NULL,NULL,'2026-09-24 14:54:55','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(81,3,NULL,'B1 · Kapitel 42 — Partizipien als Adjektive','Ergänze die passende Form.',NULL,NULL,NULL,'# B1 · Kapitel 42 — Partizipien als Adjektive\n# Ergänze die passende Form.\n\ndas ___ Kind (lachen)\n= lachende\n\ndie ___ Tür (schließen)\n= geschlossene\n\nder ___ Bus (ankommen)\n= ankommende\n\ndie ___ E-Mail (schreiben)\n= geschriebene\n\ndie ___ Studenten (lernen)\n= lernenden\n\ndas ___ Fahrrad (reparieren)\n= reparierte\n','grammar','B1',NULL,1,NULL,NULL,'2026-09-24 14:54:55','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(82,3,NULL,'B1 · Kapitel 43 — Gesamtwiederholung: Satzverknüpfung','Ergänze die passende Form.',NULL,NULL,NULL,'# B1 · Kapitel 43 — Gesamtwiederholung: Satzverknüpfung\n# Ergänze die passende Form.\n\nIch bleibe zu Hause, ___ ich krank bin.\n= weil\n\n___ es regnet, gehen wir spazieren.\n= Obwohl|obwohl\n\nIch spreche langsam, ___ du mich verstehst.\n= damit\n\nDas ist der Mann, ___ mir geholfen hat.\n= der\n\n___ ich Zeit habe, besuche ich dich.\n= Wenn|wenn\n\nDer Zug hat Verspätung. ___ komme ich später.\n= Deshalb\n','grammar','B1',NULL,1,NULL,NULL,'2026-09-24 14:54:55','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(83,1,NULL,'A1 · Kapitel 01 — Personalpronomen + sein / haben','Ergänze die passende Form.',NULL,NULL,NULL,'# A1 · Kapitel 01 — Personalpronomen + sein / haben\n# Ergänze die passende Form.\n\nIch ___ neu hier. (sein)\n= bin\n\nDu ___ einen Bruder. (haben)\n= hast\n\nEr ___ Ingenieur. (sein)\n= ist\n\nWir ___ heute Unterricht. (haben)\n= haben\n\nIhr ___ sehr pünktlich. (sein)\n= seid\n\nSie ___ zwei Kinder. (haben)\n= haben\n','grammar','A1',NULL,0,NULL,NULL,'2026-09-24 14:55:50','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(84,1,NULL,'A1 · Kapitel 02 — Präsens: regelmäßige Verben','Ergänze die passende Form.',NULL,NULL,NULL,'# A1 · Kapitel 02 — Präsens: regelmäßige Verben\n# Ergänze die passende Form.\n\nIch ___ in Magdeburg. (wohnen)\n= wohne\n\nDu ___ Deutsch. (lernen)\n= lernst\n\nSara ___ heute. (arbeiten)\n= arbeitet\n\nWir ___ eine Pause. (machen)\n= machen\n\nIhr ___ in Berlin. (wohnen)\n= wohnt\n\nDie Schüler ___ viel. (lernen)\n= lernen\n','grammar','A1',NULL,0,NULL,NULL,'2026-09-24 14:55:50','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(85,1,NULL,'A1 · Kapitel 03 — Präsens: unregelmäßige Verben','Ergänze die passende Form.',NULL,NULL,NULL,'# A1 · Kapitel 03 — Präsens: unregelmäßige Verben\n# Ergänze die passende Form.\n\nDu ___ sehr gut Deutsch. (sprechen)\n= sprichst\n\nEr ___ nach Berlin. (fahren)\n= fährt\n\nMia ___ ein Buch. (lesen)\n= liest\n\nDu ___ mir bitte. (helfen)\n= hilfst\n\nEr ___ Pizza. (essen)\n= isst\n\nDu ___ lange. (schlafen)\n= schläfst\n','grammar','A1',NULL,0,NULL,NULL,'2026-09-24 14:55:50','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(86,1,NULL,'A1 · Kapitel 05 — Nomen, Artikel und Plural','Ergänze die passende Form.',NULL,NULL,NULL,'# A1 · Kapitel 05 — Nomen, Artikel und Plural\n# Ergänze die passende Form.\n\n___ Tisch (bestimmt)\n= der\n\n___ Lampe (unbestimmt)\n= eine\n\n___ Kind (bestimmt)\n= das\n\n___ Bücher (bestimmt, Pl.)\n= die\n\n___ Wohnung (unbestimmt)\n= eine\n\n___ Auto (unbestimmt)\n= ein\n','grammar','A1',NULL,0,NULL,NULL,'2026-09-24 14:55:50','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(87,1,NULL,'A1 · Kapitel 06 — Negation: nicht oder kein?','Ergänze die passende Form.',NULL,NULL,NULL,'# A1 · Kapitel 06 — Negation: nicht oder kein?\n# Ergänze die passende Form.\n\nIch habe ___ Zeit.\n= keine\n\nDas ist ___ teuer.\n= nicht\n\nWir trinken ___ Kaffee.\n= keinen\n\nEr kommt heute ___.\n= nicht\n\nSie hat ___ Schwester.\n= keine\n\nDer Bus ist ___ pünktlich.\n= nicht\n','grammar','A1',NULL,0,NULL,NULL,'2026-09-24 14:55:50','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(88,1,NULL,'A1 · Kapitel 07 — Akkusativ','Ergänze die passende Form.',NULL,NULL,NULL,'# A1 · Kapitel 07 — Akkusativ\n# Ergänze die passende Form.\n\nIch brauche ___ Stift. (ein)\n= einen\n\nSie kauft ___ Tasche. (die)\n= die\n\nWir sehen ___ Film. (der)\n= den\n\nEr nimmt ___ Buch. (das)\n= das\n\nDu hast ___ Termin. (kein)\n= keinen\n\nIch besuche ___ Eltern. (mein)\n= meine\n','grammar','A1',NULL,0,NULL,NULL,'2026-09-24 14:55:50','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(89,1,NULL,'A1 · Kapitel 08 — Possessivartikel','Ergänze die passende Form.',NULL,NULL,NULL,'# A1 · Kapitel 08 — Possessivartikel\n# Ergänze die passende Form.\n\nDas ist ___ Buch. (ich)\n= mein\n\nWo ist ___ Tasche? (du)\n= deine\n\nEr besucht ___ Mutter. (er)\n= seine\n\nWir treffen ___ Freunde. (wir)\n= unsere\n\nHabt ihr ___ Tickets? (ihr)\n= eure\n\nWie ist ___ Adresse? (Sie)\n= Ihre\n','grammar','A1',NULL,0,NULL,NULL,'2026-09-24 14:55:50','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(90,1,NULL,'A1 · Kapitel 09 — Modalverben','Ergänze die passende Form.',NULL,NULL,NULL,'# A1 · Kapitel 09 — Modalverben\n# Ergänze die passende Form.\n\nIch ___ schwimmen. (können)\n= kann\n\nDu ___ heute lernen. (müssen)\n= musst\n\nEr ___ Arzt werden. (wollen)\n= will\n\nWir ___ hier nicht rauchen. (dürfen)\n= dürfen\n\nIhr ___ pünktlich sein. (sollen)\n= sollt\n\nSie ___ einen Tee. (möchten)\n= möchten\n','grammar','A1',NULL,0,NULL,NULL,'2026-09-24 14:55:50','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(91,1,NULL,'A1 · Kapitel 10 — Trennbare Verben + Imperativ','Ergänze die passende Form.',NULL,NULL,NULL,'# A1 · Kapitel 10 — Trennbare Verben + Imperativ\n# Ergänze die passende Form.\n\nIch ___ um 6 Uhr ___. (aufstehen)\n= stehe\n= auf\n\nDu ___ deine Mutter ___. (anrufen)\n= rufst\n= an\n\nWir ___ heute ___. (einkaufen)\n= kaufen\n= ein\n\nImperativ du: ___ die Tür! (öffnen)\n= Öffne\n\nImperativ ihr: ___ leise! (sein)\n= Seid\n\nImperativ Sie: ___ Sie hier! (warten)\n= Warten\n','grammar','A1',NULL,0,NULL,NULL,'2026-09-24 14:55:50','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(92,1,NULL,'A1 · Kapitel 11 — Perfekt: Einstieg','Ergänze die passende Form.',NULL,NULL,NULL,'# A1 · Kapitel 11 — Perfekt: Einstieg\n# Ergänze die passende Form.\n\nIch ___ Deutsch gelernt.\n= habe\n\nWir ___ nach Berlin gefahren.\n= sind\n\nSie ___ Pizza gegessen.\n= hat\n\nEr ___ spät gekommen.\n= ist\n\nDu ___ viel gearbeitet.\n= hast\n\nIhr ___ zu Hause geblieben.\n= seid\n','grammar','A1',NULL,0,NULL,NULL,'2026-09-24 14:55:50','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(93,1,NULL,'A1 · Kapitel 12 — Dativ + wichtige Präpositionen','Ergänze die passende Form.',NULL,NULL,NULL,'# A1 · Kapitel 12 — Dativ + wichtige Präpositionen\n# Ergänze die passende Form.\n\nIch fahre mit ___ Bus. (der)\n= dem\n\nSie ist bei ___ Ärztin. (die)\n= der\n\nWir kommen aus ___ Schweiz. (die)\n= der\n\nEr geht zu ___ Arzt. (ein)\n= einem\n\nIch spreche mit ___ Freunden. (mein)\n= meinen\n\nSie hilft ___ Kind. (das)\n= dem\n','grammar','A1',NULL,0,NULL,NULL,'2026-09-24 14:55:50','2026-10-21 21:19:00',NULL,'homework',NULL,NULL,NULL,1),
(94,3,NULL,'Kapitel 09 — Negation',NULL,'Heute läuft bei Leon nicht alles gut. Am Morgen hat er keine Zeit für Frühstück. Der Bus kommt nicht pünktlich, deshalb erreicht er die Arbeit zu spät. Im Büro findet er niemanden an seinem Platz, denn alle sind in einer Besprechung. Leon hat noch nicht auf seine E-Mails geantwortet und es gibt keinen Kaffee mehr. Mittags möchte er weder Pizza noch Pasta essen. Am Abend ist er aber nicht mehr gestresst: Er geht nicht ins Fitnessstudio, sondern direkt nach Hause und macht einfach nichts.\0img:/img/homework/kein-perfekter-montag.webp',8,'Lesetext — Kein perfekter Montag','# Kapitel 09 — Negation\n@learning\n{\n  \"version\": 1,\n  \"key\": \"kapitel-09-negation\",\n  \"title\": \"Kapitel 09 — Negation\",\n  \"label\": \"Kapitel 09\",\n  \"sections\": [\n    {\n      \"id\": \"exercise-1\",\n      \"label\": \"Übung 1\",\n      \"title\": \"Übung 1 – nicht oder kein?\",\n      \"instruction\": \"Ergänze die richtige Negation in passender Form.\",\n      \"examples\": [\n        {\n          \"prompt\": \"Ich habe ___ Fahrrad.\",\n          \"answer\": \"Ich habe kein Fahrrad.\",\n          \"explanation\": \"Nomen: Fahrrad → kein.\"\n        },\n        {\n          \"prompt\": \"Das Fahrrad ist ___ teuer.\",\n          \"answer\": \"Das Fahrrad ist nicht teuer.\",\n          \"explanation\": \"Adjektiv: teuer → nicht.\"\n        }\n      ],\n      \"questions\": [\n        {\n          \"id\": \"1\",\n          \"type\": \"fill_blank\",\n          \"prompt\": \"Ich habe ___ Auto.\",\n          \"accepted\": [\n            \"kein\"\n          ],\n          \"hints\": [\n            \"Schau auf das Wort nach der Lücke: Ist es ein Nomen?\",\n            \"Auto ist Neutrum und steht hier im Akkusativ.\"\n          ],\n          \"feedback\": \"Richtig: kein Auto.\"\n        },\n        {\n          \"id\": \"2\",\n          \"type\": \"fill_blank\",\n          \"prompt\": \"Das Auto ist ___ neu.\",\n          \"accepted\": [\n            \"nicht\"\n          ],\n          \"hints\": [\n            \"Was wird verneint: ein Nomen oder die Eigenschaft „neu“?\",\n            \"Adjektive werden normalerweise mit nicht verneint.\"\n          ],\n          \"feedback\": \"Richtig: nicht neu.\"\n        },\n        {\n          \"id\": \"3\",\n          \"type\": \"fill_blank\",\n          \"prompt\": \"Wir trinken ___ Kaffee.\",\n          \"accepted\": [\n            \"keinen\"\n          ],\n          \"hints\": [\n            \"Kaffee ist ein Nomen.\",\n            \"Kaffee ist maskulin und steht im Akkusativ.\"\n          ],\n          \"feedback\": \"Richtig: keinen Kaffee.\"\n        },\n        {\n          \"id\": \"4\",\n          \"type\": \"fill_blank\",\n          \"prompt\": \"Sie kommt heute ___.\",\n          \"accepted\": [\n            \"nicht\"\n          ],\n          \"hints\": [\n            \"Hier wird die Handlung „kommen“ verneint.\",\n            \"Für die Verneinung der Handlung verwendest du nicht.\"\n          ],\n          \"feedback\": \"Richtig: Sie kommt heute nicht.\"\n        },\n        {\n          \"id\": \"5\",\n          \"type\": \"fill_blank\",\n          \"prompt\": \"Das ist ___ mein Buch.\",\n          \"accepted\": [\n            \"nicht\"\n          ],\n          \"hints\": [\n            \"Vor „mein Buch“ steht schon ein Possessivartikel.\",\n            \"Mit Possessivartikeln verwendest du hier nicht.\"\n          ],\n          \"feedback\": \"Richtig: Das ist nicht mein Buch.\"\n        },\n        {\n          \"id\": \"6\",\n          \"type\": \"fill_blank\",\n          \"prompt\": \"Er hat ___ Zeit.\",\n          \"accepted\": [\n            \"keine\"\n          ],\n          \"hints\": [\n            \"Zeit ist ein Nomen.\",\n            \"Zeit ist feminin.\"\n          ],\n          \"feedback\": \"Richtig: keine Zeit.\"\n        },\n        {\n          \"id\": \"7\",\n          \"type\": \"fill_blank\",\n          \"prompt\": \"Ich kenne dort ___ Mann.\",\n          \"accepted\": [\n            \"keinen\"\n          ],\n          \"hints\": [\n            \"Mann ist ein Nomen.\",\n            \"Mann ist maskulin und steht im Akkusativ.\"\n          ],\n          \"feedback\": \"Richtig: keinen Mann. Diese Formulierung wurde gegenüber der Vorlage bewusst eindeutig gemacht.\"\n        },\n        {\n          \"id\": \"8\",\n          \"type\": \"fill_blank\",\n          \"prompt\": \"Wir fahren ___ mit dem Auto.\",\n          \"accepted\": [\n            \"nicht\"\n          ],\n          \"hints\": [\n            \"Hier wird die Handlung bzw. Art des Fahrens verneint.\",\n            \"Setze nicht vor die Präpositionalgruppe.\"\n          ],\n          \"feedback\": \"Richtig: Wir fahren nicht mit dem Auto.\"\n        }\n      ],\n      \"objective\": \"nicht vs. kein/keine/keinen erkennen und die passende Form einsetzen.\"\n    },\n    {\n      \"id\": \"exercise-2\",\n      \"label\": \"Übung 2\",\n      \"title\": \"Übung 2 – kein deklinieren\",\n      \"instruction\": \"Setze die richtige Form von kein ein.\",\n      \"examples\": [\n        {\n          \"prompt\": \"Ich sehe ___ Hund. (Akk., m.)\",\n          \"answer\": \"Ich sehe keinen Hund.\",\n          \"explanation\": \"Akkusativ + maskulin → keinen.\"\n        },\n        {\n          \"prompt\": \"Sie spricht mit ___ Freundin. (Dat., f.)\",\n          \"answer\": \"Sie spricht mit keiner Freundin.\",\n          \"explanation\": \"Dativ + feminin → keiner.\"\n        }\n      ],\n      \"questions\": [\n        {\n          \"id\": \"9\",\n          \"type\": \"fill_blank\",\n          \"prompt\": \"Ich habe ___ Termin. (Akk., m.)\",\n          \"accepted\": [\n            \"keinen\"\n          ],\n          \"hints\": [\n            \"Bestimme zuerst Kasus und Genus.\",\n            \"Akkusativ + maskulin hat die Endung -en.\"\n          ],\n          \"feedback\": \"Richtig: keinen Termin.\"\n        },\n        {\n          \"id\": \"10\",\n          \"type\": \"fill_blank\",\n          \"prompt\": \"Sie hat ___ Tasche. (Akk., f.)\",\n          \"accepted\": [\n            \"keine\"\n          ],\n          \"hints\": [\n            \"Tasche ist feminin.\",\n            \"Akkusativ feminin → keine.\"\n          ],\n          \"feedback\": \"Richtig: keine Tasche.\"\n        },\n        {\n          \"id\": \"11\",\n          \"type\": \"fill_blank\",\n          \"prompt\": \"Wir helfen ___ Kunden. (Dat., m.)\",\n          \"accepted\": [\n            \"keinem\"\n          ],\n          \"hints\": [\n            \"Das Verb helfen verlangt Dativ.\",\n            \"Dativ maskulin → keinem.\"\n          ],\n          \"feedback\": \"Richtig: keinem Kunden.\"\n        },\n        {\n          \"id\": \"12\",\n          \"type\": \"fill_blank\",\n          \"prompt\": \"Er spricht mit ___ Kolleginnen. (Dat., Pl.)\",\n          \"accepted\": [\n            \"keinen\"\n          ],\n          \"hints\": [\n            \"Die Präposition mit verlangt Dativ.\",\n            \"Dativ Plural → keinen; das Nomen trägt hier bereits die Pluralform.\"\n          ],\n          \"feedback\": \"Richtig: mit keinen Kolleginnen.\"\n        },\n        {\n          \"id\": \"13\",\n          \"type\": \"fill_blank\",\n          \"prompt\": \"Das ist ___ Problem. (Nom., n.)\",\n          \"accepted\": [\n            \"kein\"\n          ],\n          \"hints\": [\n            \"Problem ist Neutrum.\",\n            \"Nominativ Neutrum → kein.\"\n          ],\n          \"feedback\": \"Richtig: kein Problem.\"\n        },\n        {\n          \"id\": \"14\",\n          \"type\": \"fill_blank\",\n          \"prompt\": \"Wegen ___ Fehlers wurde der Termin verschoben. (Gen., m.; formell)\",\n          \"accepted\": [\n            \"keines\"\n          ],\n          \"hints\": [\n            \"Wegen kann formell mit Genitiv stehen.\",\n            \"Genitiv maskulin → keines.\"\n          ],\n          \"feedback\": \"Richtig: wegen keines Fehlers.\"\n        }\n      ],\n      \"objective\": \"kein nach Kasus, Genus und Numerus korrekt deklinieren.\"\n    },\n    {\n      \"id\": \"exercise-3\",\n      \"label\": \"Übung 3\",\n      \"title\": \"Übung 3 – Stellung von nicht\",\n      \"instruction\": \"Setze „nicht“ an die passende Stelle. Die Information in Klammern soll verneint werden.\",\n      \"examples\": [\n        {\n          \"prompt\": \"Ich fahre heute mit dem Bus. (mit dem Bus)\",\n          \"answer\": \"Ich fahre heute nicht mit dem Bus.\",\n          \"explanation\": \"nicht steht direkt vor dem verneinten Satzteil.\"\n        },\n        {\n          \"prompt\": \"Das Zimmer ist sehr groß. (groß)\",\n          \"answer\": \"Das Zimmer ist nicht sehr groß.\",\n          \"explanation\": \"Bei Adjektiven steht nicht vor der Adjektivgruppe.\"\n        }\n      ],\n      \"questions\": [\n        {\n          \"id\": \"15\",\n          \"type\": \"insert_word\",\n          \"prompt\": \"Ich fahre morgen mit dem Auto. (mit dem Auto)\",\n          \"accepted\": [\n            \"Ich fahre morgen nicht mit dem Auto.\"\n          ],\n          \"hints\": [\n            \"Welcher Satzteil soll verneint werden?\",\n            \"Setze nicht direkt vor „mit dem Auto“.\"\n          ],\n          \"feedback\": \"Richtig: Ich fahre morgen nicht mit dem Auto.\",\n          \"tokens\": [\n            \"Ich\",\n            \"fahre\",\n            \"morgen\",\n            \"mit\",\n            \"dem\",\n            \"Auto.\"\n          ],\n          \"word\": \"nicht\",\n          \"positions\": [\n            3\n          ]\n        },\n        {\n          \"id\": \"16\",\n          \"type\": \"insert_word\",\n          \"prompt\": \"Wir treffen uns am Montag. (am Montag)\",\n          \"accepted\": [\n            \"Wir treffen uns nicht am Montag.\"\n          ],\n          \"hints\": [\n            \"Der Zeitpunkt soll verneint werden.\",\n            \"Setze nicht direkt vor „am Montag“.\"\n          ],\n          \"feedback\": \"Richtig: Wir treffen uns nicht am Montag.\",\n          \"tokens\": [\n            \"Wir\",\n            \"treffen\",\n            \"uns\",\n            \"am\",\n            \"Montag.\"\n          ],\n          \"word\": \"nicht\",\n          \"positions\": [\n            3\n          ]\n        },\n        {\n          \"id\": \"17\",\n          \"type\": \"insert_word\",\n          \"prompt\": \"Anna kommt heute. (Anna – Kontrast: nicht Anna, sondern jemand anderes)\",\n          \"accepted\": [\n            \"Nicht Anna kommt heute.\"\n          ],\n          \"hints\": [\n            \"Hier wird ausdrücklich die Person kontrastiert.\",\n            \"Bei Fokusnegation kann nicht direkt vor dem Namen stehen.\"\n          ],\n          \"feedback\": \"Richtig als Kontrastfokus: Nicht Anna kommt heute. Die UI soll den Zusatz „sondern jemand anderes“ als Erklärung anzeigen.\",\n          \"tokens\": [\n            \"Anna\",\n            \"kommt\",\n            \"heute.\"\n          ],\n          \"word\": \"nicht\",\n          \"positions\": [\n            0\n          ]\n        },\n        {\n          \"id\": \"18\",\n          \"type\": \"insert_word\",\n          \"prompt\": \"Das Essen ist sehr teuer. (teuer)\",\n          \"accepted\": [\n            \"Das Essen ist nicht sehr teuer.\"\n          ],\n          \"hints\": [\n            \"Die Eigenschaft wird verneint.\",\n            \"Setze nicht vor die Adjektivgruppe „sehr teuer“.\"\n          ],\n          \"feedback\": \"Richtig: Das Essen ist nicht sehr teuer.\",\n          \"tokens\": [\n            \"Das\",\n            \"Essen\",\n            \"ist\",\n            \"sehr\",\n            \"teuer.\"\n          ],\n          \"word\": \"nicht\",\n          \"positions\": [\n            3\n          ]\n        },\n        {\n          \"id\": \"19\",\n          \"type\": \"insert_word\",\n          \"prompt\": \"Er kann morgen kommen. (kommen / ganze Handlung)\",\n          \"accepted\": [\n            \"Er kann morgen nicht kommen.\"\n          ],\n          \"hints\": [\n            \"Bei Modalverb + Infinitiv steht nicht oft vor dem Infinitiv.\",\n            \"Setze nicht vor „kommen“.\"\n          ],\n          \"feedback\": \"Richtig: Er kann morgen nicht kommen.\",\n          \"tokens\": [\n            \"Er\",\n            \"kann\",\n            \"morgen\",\n            \"kommen.\"\n          ],\n          \"word\": \"nicht\",\n          \"positions\": [\n            3\n          ]\n        }\n      ],\n      \"objective\": \"nicht abhängig vom verneinten Satzteil an die natürliche Position setzen.\"\n    },\n    {\n      \"id\": \"exercise-4\",\n      \"label\": \"Übung 4\",\n      \"title\": \"Übung 4 – nichts, niemand, nie oder nirgendwo\",\n      \"instruction\": \"Ergänze das passende Wort.\",\n      \"examples\": [\n        {\n          \"prompt\": \"Ich esse ___.\",\n          \"answer\": \"Ich esse nichts.\",\n          \"explanation\": \"Sache/Objekt → nichts.\"\n        },\n        {\n          \"prompt\": \"___ wartet vor der Tür.\",\n          \"answer\": \"Niemand wartet vor der Tür.\",\n          \"explanation\": \"Person → niemand.\"\n        }\n      ],\n      \"questions\": [\n        {\n          \"id\": \"20\",\n          \"type\": \"fill_blank_adaptive\",\n          \"prompt\": \"Ich sehe ___.\",\n          \"accepted\": [\n            \"nichts\"\n          ],\n          \"hints\": [\n            \"Geht es um eine Person, Sache, Zeit oder einen Ort?\",\n            \"Hier geht es um eine Sache/etwas.\"\n          ],\n          \"feedback\": \"Richtig: nichts.\",\n          \"wordBank\": [\n            \"nichts\",\n            \"niemand\",\n            \"nie\",\n            \"nirgendwo\"\n          ]\n        },\n        {\n          \"id\": \"21\",\n          \"type\": \"fill_blank_adaptive\",\n          \"prompt\": \"___ ist im Büro.\",\n          \"accepted\": [\n            \"niemand\"\n          ],\n          \"hints\": [\n            \"Gesucht ist eine Person.\",\n            \"Am Satzanfang wird das Wort großgeschrieben.\"\n          ],\n          \"feedback\": \"Richtig: Niemand.\",\n          \"wordBank\": [\n            \"nichts\",\n            \"niemand\",\n            \"nie\",\n            \"nirgendwo\"\n          ]\n        },\n        {\n          \"id\": \"22\",\n          \"type\": \"fill_blank_adaptive\",\n          \"prompt\": \"Ich rauche ___.\",\n          \"accepted\": [\n            \"nie\"\n          ],\n          \"hints\": [\n            \"Gesucht ist ein Ausdruck für „zu keiner Zeit“.\",\n            \"Zeit/Häufigkeit → nie.\"\n          ],\n          \"feedback\": \"Richtig: nie.\",\n          \"wordBank\": [\n            \"nichts\",\n            \"niemand\",\n            \"nie\",\n            \"nirgendwo\"\n          ]\n        },\n        {\n          \"id\": \"23\",\n          \"type\": \"fill_blank_adaptive\",\n          \"prompt\": \"Ich finde meinen Schlüssel ___.\",\n          \"accepted\": [\n            \"nirgendwo\"\n          ],\n          \"hints\": [\n            \"Gesucht ist ein Ort.\",\n            \"Ort → nirgendwo.\"\n          ],\n          \"feedback\": \"Richtig: nirgendwo.\",\n          \"wordBank\": [\n            \"nichts\",\n            \"niemand\",\n            \"nie\",\n            \"nirgendwo\"\n          ]\n        },\n        {\n          \"id\": \"24\",\n          \"type\": \"fill_blank_adaptive\",\n          \"prompt\": \"Ich kenne hier ___.\",\n          \"accepted\": [\n            \"niemanden\"\n          ],\n          \"hints\": [\n            \"Gesucht ist eine Person im Akkusativ.\",\n            \"niemand bekommt hier die Akkusativendung -en.\"\n          ],\n          \"feedback\": \"Richtig: niemanden.\",\n          \"wordBank\": [\n            \"nichts\",\n            \"niemand\",\n            \"nie\",\n            \"nirgendwo\"\n          ]\n        },\n        {\n          \"id\": \"25\",\n          \"type\": \"fill_blank_adaptive\",\n          \"prompt\": \"Es gibt ___ Neues.\",\n          \"accepted\": [\n            \"nichts\"\n          ],\n          \"hints\": [\n            \"Gesucht ist „keine Sache / nichts“.\",\n            \"Nach nichts kann ein substantiviertes Adjektiv stehen: nichts Neues.\"\n          ],\n          \"feedback\": \"Richtig: nichts Neues.\",\n          \"wordBank\": [\n            \"nichts\",\n            \"niemand\",\n            \"nie\",\n            \"nirgendwo\"\n          ]\n        }\n      ],\n      \"objective\": \"Negativpronomen und Adverbien nach Bedeutung unterscheiden.\"\n    },\n    {\n      \"id\": \"exercise-5\",\n      \"label\": \"Übung 5\",\n      \"title\": \"Übung 5 – noch nicht / nicht mehr / noch nie\",\n      \"instruction\": \"Ergänze den passenden Ausdruck.\",\n      \"examples\": [\n        {\n          \"prompt\": \"Ich habe die Hausaufgaben ___ gemacht; ich mache sie später.\",\n          \"answer\": \"noch nicht\",\n          \"explanation\": \"Bis jetzt nicht, aber später wahrscheinlich → noch nicht.\"\n        },\n        {\n          \"prompt\": \"Früher spielte er Fußball; heute spielt er ___.\",\n          \"answer\": \"nicht mehr\",\n          \"explanation\": \"Früher ja, jetzt nein → nicht mehr.\"\n        }\n      ],\n      \"questions\": [\n        {\n          \"id\": \"26\",\n          \"type\": \"phrase_fill\",\n          \"prompt\": \"Ich habe ___ gegessen; ich esse später.\",\n          \"accepted\": [\n            \"noch nicht\"\n          ],\n          \"hints\": [\n            \"Ist die Handlung bis jetzt nicht passiert, kann aber später passieren?\",\n            \"Dann verwendest du noch nicht.\"\n          ],\n          \"feedback\": \"Richtig: noch nicht.\"\n        },\n        {\n          \"id\": \"27\",\n          \"type\": \"phrase_fill\",\n          \"prompt\": \"Früher wohnte ich hier, aber jetzt wohne ich hier ___.\",\n          \"accepted\": [\n            \"nicht mehr\"\n          ],\n          \"hints\": [\n            \"Früher ja, jetzt nein.\",\n            \"Dieser Wechsel wird mit nicht mehr ausgedrückt.\"\n          ],\n          \"feedback\": \"Richtig: nicht mehr.\"\n        },\n        {\n          \"id\": \"28\",\n          \"type\": \"phrase_fill\",\n          \"prompt\": \"Ich war ___ in Österreich.\",\n          \"accepted\": [\n            \"noch nie\",\n            \"nie\"\n          ],\n          \"hints\": [\n            \"Geht es um eine Erfahrung bis zum heutigen Zeitpunkt?\",\n            \"noch nie betont „bis jetzt“. Auch nie ist grammatisch korrekt.\"\n          ],\n          \"feedback\": \"Bevorzugt: noch nie. Akzeptiert wird auch: nie.\"\n        },\n        {\n          \"id\": \"29\",\n          \"type\": \"phrase_fill\",\n          \"prompt\": \"Der Kurs ist ___ zu Ende.\",\n          \"accepted\": [\n            \"noch nicht\"\n          ],\n          \"hints\": [\n            \"Der Kurs läuft im Moment weiter.\",\n            \"Bis jetzt nicht beendet → noch nicht.\"\n          ],\n          \"feedback\": \"Richtig: noch nicht.\"\n        },\n        {\n          \"id\": \"30\",\n          \"type\": \"phrase_fill\",\n          \"prompt\": \"Wir haben ___ Kaffee ___; alles ist aufgebraucht.\",\n          \"accepted\": [\n            [\n              \"keinen\",\n              \"mehr\"\n            ]\n          ],\n          \"hints\": [\n            \"Hier brauchst du zwei Teile.\",\n            \"Vor Kaffee steht die Form von kein; nach Kaffee steht mehr.\"\n          ],\n          \"feedback\": \"Richtig: keinen Kaffee mehr.\"\n        }\n      ],\n      \"objective\": \"zeitliche Negationsausdrücke nach Bedeutung unterscheiden.\"\n    },\n    {\n      \"id\": \"exercise-6\",\n      \"label\": \"Übung 6\",\n      \"title\": \"Übung 6 – weder … noch / sondern\",\n      \"instruction\": \"Verbinde die Aussagen. Schreibe zuerst selbst; bei Schwierigkeiten erhältst du schrittweise Hilfe.\",\n      \"examples\": [\n        {\n          \"prompt\": \"Ich esse kein Fleisch. Ich esse keinen Fisch.\",\n          \"answer\": \"Ich esse weder Fleisch noch Fisch.\",\n          \"explanation\": \"Zwei negative Alternativen → weder … noch.\"\n        },\n        {\n          \"prompt\": \"Sie fährt nicht heute. Sie fährt morgen.\",\n          \"answer\": \"Sie fährt nicht heute, sondern morgen.\",\n          \"explanation\": \"Korrektur/Kontrast → sondern.\"\n        }\n      ],\n      \"questions\": [\n        {\n          \"id\": \"31\",\n          \"type\": \"sentence_transform_adaptive\",\n          \"prompt\": \"Ich trinke keinen Kaffee. Ich trinke keinen Tee.\",\n          \"accepted\": [\n            \"Ich trinke weder Kaffee noch Tee.\",\n            \"Weder Kaffee noch Tee trinke ich.\"\n          ],\n          \"hints\": [\n            \"Sind beide Möglichkeiten negativ?\",\n            \"Verwende weder vor Kaffee und noch vor Tee.\"\n          ],\n          \"feedback\": \"Richtig: Ich trinke weder Kaffee noch Tee.\",\n          \"skeleton\": \"Ich trinke ___ Kaffee ___ Tee.\",\n          \"builderWords\": [\n            \"weder\",\n            \"noch\",\n            \"sondern\"\n          ]\n        },\n        {\n          \"id\": \"32\",\n          \"type\": \"sentence_transform_adaptive\",\n          \"prompt\": \"Er kommt nicht heute. Er kommt morgen.\",\n          \"accepted\": [\n            \"Er kommt nicht heute, sondern morgen.\",\n            \"Er kommt heute nicht, sondern morgen.\"\n          ],\n          \"hints\": [\n            \"Die zweite Aussage korrigiert die erste.\",\n            \"Verbinde mit sondern.\"\n          ],\n          \"feedback\": \"Richtig: Er kommt heute nicht, sondern morgen.\",\n          \"skeleton\": \"Er kommt nicht heute, ___ morgen.\",\n          \"builderWords\": [\n            \"weder\",\n            \"noch\",\n            \"sondern\"\n          ]\n        },\n        {\n          \"id\": \"33\",\n          \"type\": \"sentence_transform_adaptive\",\n          \"prompt\": \"Das ist kein Hotel. Das ist ein Büro.\",\n          \"accepted\": [\n            \"Das ist kein Hotel, sondern ein Büro.\"\n          ],\n          \"hints\": [\n            \"Die zweite Aussage stellt richtig, was es ist.\",\n            \"Nach der negativen Aussage passt sondern.\"\n          ],\n          \"feedback\": \"Richtig: Das ist kein Hotel, sondern ein Büro.\",\n          \"skeleton\": \"Das ist kein Hotel, ___ ein Büro.\",\n          \"builderWords\": [\n            \"weder\",\n            \"noch\",\n            \"sondern\"\n          ]\n        },\n        {\n          \"id\": \"34\",\n          \"type\": \"sentence_transform_adaptive\",\n          \"prompt\": \"Sie spricht nicht Französisch. Sie spricht nicht Spanisch.\",\n          \"accepted\": [\n            \"Sie spricht weder Französisch noch Spanisch.\",\n            \"Weder Französisch noch Spanisch spricht sie.\"\n          ],\n          \"hints\": [\n            \"Beide Sprachen werden ausgeschlossen.\",\n            \"Verwende weder … noch.\"\n          ],\n          \"feedback\": \"Richtig: Sie spricht weder Französisch noch Spanisch.\",\n          \"skeleton\": \"Sie spricht ___ Französisch ___ Spanisch.\",\n          \"builderWords\": [\n            \"weder\",\n            \"noch\",\n            \"sondern\"\n          ]\n        }\n      ],\n      \"objective\": \"zwei Aussagen mit weder … noch oder sondern korrekt verbinden.\"\n    },\n    {\n      \"id\": \"exercise-7\",\n      \"label\": \"Übung 7\",\n      \"title\": \"Übung 7 – Fehler korrigieren\",\n      \"instruction\": \"Korrigiere den Satz. Bearbeite möglichst nur die Stelle, die falsch ist.\",\n      \"examples\": [\n        {\n          \"prompt\": \"Ich habe nicht Auto.\",\n          \"answer\": \"Ich habe kein Auto.\",\n          \"explanation\": \"Nomen ohne bestimmten Artikel → kein.\"\n        },\n        {\n          \"prompt\": \"Das Wetter ist kein schön.\",\n          \"answer\": \"Das Wetter ist nicht schön.\",\n          \"explanation\": \"Adjektiv → nicht.\"\n        }\n      ],\n      \"questions\": [\n        {\n          \"id\": \"35\",\n          \"type\": \"sentence_correction\",\n          \"prompt\": \"Ich habe nicht Geld.\",\n          \"accepted\": [\n            \"Ich habe kein Geld.\"\n          ],\n          \"hints\": [\n            \"Was wird verneint: ein Nomen oder eine Eigenschaft?\",\n            \"Geld ist ein Nomen.\"\n          ],\n          \"feedback\": \"Richtig: Ich habe kein Geld.\"\n        },\n        {\n          \"id\": \"36\",\n          \"type\": \"sentence_correction\",\n          \"prompt\": \"Niemand kommt nicht.\",\n          \"accepted\": [\n            \"Niemand kommt.\"\n          ],\n          \"hints\": [\n            \"Achte auf doppelte Negation.\",\n            \"Niemand enthält die Negation schon.\"\n          ],\n          \"feedback\": \"Richtig: Niemand kommt.\"\n        },\n        {\n          \"id\": \"37\",\n          \"type\": \"sentence_correction\",\n          \"prompt\": \"Das ist kein interessant.\",\n          \"accepted\": [\n            \"Das ist nicht interessant.\"\n          ],\n          \"hints\": [\n            \"interessant ist ein Adjektiv.\",\n            \"Adjektiv → nicht.\"\n          ],\n          \"feedback\": \"Richtig: Das ist nicht interessant.\"\n        },\n        {\n          \"id\": \"38\",\n          \"type\": \"sentence_correction\",\n          \"prompt\": \"Ich war nicht nie in Berlin.\",\n          \"accepted\": [\n            \"Ich war noch nie in Berlin.\",\n            \"Ich war nie in Berlin.\"\n          ],\n          \"hints\": [\n            \"Hier stehen zwei Negationen unnötig zusammen.\",\n            \"Verwende nie oder – für „bis jetzt“ – noch nie.\"\n          ],\n          \"feedback\": \"Bevorzugt: Ich war noch nie in Berlin. Akzeptiert: Ich war nie in Berlin.\"\n        },\n        {\n          \"id\": \"39\",\n          \"type\": \"sentence_correction\",\n          \"prompt\": \"Wir haben nicht Milch mehr.\",\n          \"accepted\": [\n            \"Wir haben keine Milch mehr.\"\n          ],\n          \"hints\": [\n            \"Milch ist ein Nomen.\",\n            \"Feminin: keine; mehr steht nach dem Nomen.\"\n          ],\n          \"feedback\": \"Richtig: Wir haben keine Milch mehr.\"\n        }\n      ],\n      \"objective\": \"typische Fehler bei der Negation erkennen und selbst korrigieren.\"\n    },\n    {\n      \"id\": \"reading\",\n      \"label\": \"Lesetext\",\n      \"title\": \"Lesetext — Kein perfekter Montag\",\n      \"instruction\": \"Lies den Text und bearbeite die Aufgaben.\",\n      \"questions\": [\n        {\n          \"id\": \"reading-1\",\n          \"title\": \"Aufgabe 1 – Markieren\",\n          \"type\": \"text_highlight\",\n          \"prompt\": \"Markiere alle Negations- und Kontrastausdrücke im Text.\",\n          \"hints\": [\n            \"Suche nach nicht, Formen von kein, Negativpronomen und Konnektoren.\",\n            \"Es gibt 11 zu markierende Ausdrücke, wenn mehrteilige Ausdrücke als Einheit gezählt werden.\"\n          ],\n          \"feedback\": \"Die Markierungen werden direkt im Text geprüft; mehrteilige Ausdrücke werden als zusammengehörige Gruppe gespeichert.\",\n          \"examples\": [\n            {\n              \"prompt\": \"„Der Bus ist nicht pünktlich.“ → Markiere „nicht“.\"\n            }\n          ],\n          \"tokens\": [\n            \"Heute\",\n            \"läuft\",\n            \"bei\",\n            \"Leon\",\n            \"nicht\",\n            \"alles\",\n            \"gut.\",\n            \"Am\",\n            \"Morgen\",\n            \"hat\",\n            \"er\",\n            \"keine\",\n            \"Zeit\",\n            \"für\",\n            \"Frühstück.\",\n            \"Der\",\n            \"Bus\",\n            \"kommt\",\n            \"nicht\",\n            \"pünktlich,\",\n            \"deshalb\",\n            \"erreicht\",\n            \"er\",\n            \"die\",\n            \"Arbeit\",\n            \"zu\",\n            \"spät.\",\n            \"Im\",\n            \"Büro\",\n            \"findet\",\n            \"er\",\n            \"niemanden\",\n            \"an\",\n            \"seinem\",\n            \"Platz,\",\n            \"denn\",\n            \"alle\",\n            \"sind\",\n            \"in\",\n            \"einer\",\n            \"Besprechung.\",\n            \"Leon\",\n            \"hat\",\n            \"noch\",\n            \"nicht\",\n            \"auf\",\n            \"seine\",\n            \"E-Mails\",\n            \"geantwortet\",\n            \"und\",\n            \"es\",\n            \"gibt\",\n            \"keinen\",\n            \"Kaffee\",\n            \"mehr.\",\n            \"Mittags\",\n            \"möchte\",\n            \"er\",\n            \"weder\",\n            \"Pizza\",\n            \"noch\",\n            \"Pasta\",\n            \"essen.\",\n            \"Am\",\n            \"Abend\",\n            \"ist\",\n            \"er\",\n            \"aber\",\n            \"nicht\",\n            \"mehr\",\n            \"gestresst:\",\n            \"Er\",\n            \"geht\",\n            \"nicht\",\n            \"ins\",\n            \"Fitnessstudio,\",\n            \"sondern\",\n            \"direkt\",\n            \"nach\",\n            \"Hause\",\n            \"und\",\n            \"macht\",\n            \"einfach\",\n            \"nichts.\"\n          ],\n          \"groups\": [\n            {\n              \"id\": \"expression-1\",\n              \"label\": \"nicht (nicht alles)\",\n              \"category\": \"nicht\",\n              \"tokens\": [\n                4\n              ]\n            },\n            {\n              \"id\": \"expression-2\",\n              \"label\": \"keine\",\n              \"category\": \"kein\",\n              \"tokens\": [\n                11\n              ]\n            },\n            {\n              \"id\": \"expression-3\",\n              \"label\": \"nicht (nicht pünktlich)\",\n              \"category\": \"nicht\",\n              \"tokens\": [\n                18\n              ]\n            },\n            {\n              \"id\": \"expression-4\",\n              \"label\": \"niemanden\",\n              \"category\": \"Negativpronomen\",\n              \"tokens\": [\n                31\n              ]\n            },\n            {\n              \"id\": \"expression-5\",\n              \"label\": \"noch nicht\",\n              \"category\": \"Zeit-/Verlaufs-Ausdruck\",\n              \"tokens\": [\n                43,\n                44\n              ]\n            },\n            {\n              \"id\": \"expression-6\",\n              \"label\": \"keinen … mehr\",\n              \"category\": \"kein\",\n              \"tokens\": [\n                52,\n                54\n              ]\n            },\n            {\n              \"id\": \"expression-7\",\n              \"label\": \"weder … noch\",\n              \"category\": \"Konnektor\",\n              \"tokens\": [\n                58,\n                60\n              ]\n            },\n            {\n              \"id\": \"expression-8\",\n              \"label\": \"nicht mehr\",\n              \"category\": \"Zeit-/Verlaufs-Ausdruck\",\n              \"tokens\": [\n                68,\n                69\n              ]\n            },\n            {\n              \"id\": \"expression-9\",\n              \"label\": \"nicht (nicht ins Fitnessstudio)\",\n              \"category\": \"nicht\",\n              \"tokens\": [\n                73\n              ]\n            },\n            {\n              \"id\": \"expression-10\",\n              \"label\": \"sondern\",\n              \"category\": \"Konnektor\",\n              \"tokens\": [\n                76\n              ]\n            },\n            {\n              \"id\": \"expression-11\",\n              \"label\": \"nichts\",\n              \"category\": \"Negativpronomen\",\n              \"tokens\": [\n                83\n              ]\n            }\n          ]\n        },\n        {\n          \"id\": \"reading-2\",\n          \"title\": \"Aufgabe 2 – Sortieren\",\n          \"type\": \"categorize\",\n          \"prompt\": \"Ordne die markierten Ausdrücke der passenden Kategorie zu.\",\n          \"hints\": [\n            \"Frage dich: Nomen-Verneinung, Person/Sache, Zeitverlauf oder Verbindung/Kontrast?\",\n            \"weder … noch und sondern gehören zu den Konnektoren.\"\n          ],\n          \"feedback\": \"Nach dem Sortieren zeigt die UI pro Kategorie eine kurze Regel.\",\n          \"examples\": [\n            {\n              \"prompt\": \"„niemanden“ → Negativpronomen.\"\n            }\n          ],\n          \"items\": [\n            {\n              \"id\": \"expression-1\",\n              \"label\": \"nicht (nicht alles)\",\n              \"category\": \"nicht\"\n            },\n            {\n              \"id\": \"expression-2\",\n              \"label\": \"keine\",\n              \"category\": \"kein\"\n            },\n            {\n              \"id\": \"expression-3\",\n              \"label\": \"nicht (nicht pünktlich)\",\n              \"category\": \"nicht\"\n            },\n            {\n              \"id\": \"expression-4\",\n              \"label\": \"niemanden\",\n              \"category\": \"Negativpronomen\"\n            },\n            {\n              \"id\": \"expression-5\",\n              \"label\": \"noch nicht\",\n              \"category\": \"Zeit-/Verlaufs-Ausdruck\"\n            },\n            {\n              \"id\": \"expression-6\",\n              \"label\": \"keinen … mehr\",\n              \"category\": \"kein\"\n            },\n            {\n              \"id\": \"expression-7\",\n              \"label\": \"weder … noch\",\n              \"category\": \"Konnektor\"\n            },\n            {\n              \"id\": \"expression-8\",\n              \"label\": \"nicht mehr\",\n              \"category\": \"Zeit-/Verlaufs-Ausdruck\"\n            },\n            {\n              \"id\": \"expression-9\",\n              \"label\": \"nicht (nicht ins Fitnessstudio)\",\n              \"category\": \"nicht\"\n            },\n            {\n              \"id\": \"expression-10\",\n              \"label\": \"sondern\",\n              \"category\": \"Konnektor\"\n            },\n            {\n              \"id\": \"expression-11\",\n              \"label\": \"nichts\",\n              \"category\": \"Negativpronomen\"\n            }\n          ],\n          \"categories\": [\n            \"nicht\",\n            \"kein\",\n            \"Negativpronomen\",\n            \"Zeit-/Verlaufs-Ausdruck\",\n            \"Konnektor\"\n          ],\n          \"rules\": {\n            \"nicht\": \"nicht verneint hier Satzteile oder Handlungen.\",\n            \"kein\": \"kein verneint Nomen mit unbestimmtem oder ohne Artikel.\",\n            \"Negativpronomen\": \"niemanden bezeichnet Personen, nichts bezeichnet Sachen.\",\n            \"Zeit-/Verlaufs-Ausdruck\": \"noch nicht und nicht mehr beschreiben einen zeitlichen Verlauf.\",\n            \"Konnektor\": \"weder … noch schließt beide Alternativen aus; sondern korrigiert eine negative Aussage.\"\n          }\n        },\n        {\n          \"id\": \"reading-3\",\n          \"title\": \"Aufgabe 3 – Textverständnis\",\n          \"type\": \"short_answer\",\n          \"prompt\": \"Was hat Leon noch nicht gemacht? Antworte in einem ganzen Satz.\",\n          \"hints\": [\n            \"Suche im Text nach „noch nicht“.\",\n            \"Die Stelle steht im Satz mit den E-Mails.\"\n          ],\n          \"feedback\": \"Richtig verstanden und in einem ganzen Satz geantwortet.\",\n          \"examples\": [\n            {\n              \"prompt\": \"„Er hat noch nicht gefrühstückt.“\"\n            }\n          ],\n          \"accepted\": [\n            \"Leon hat noch nicht auf seine E-Mails geantwortet.\",\n            \"Er hat noch nicht auf seine E-Mails geantwortet.\",\n            \"Leon hat noch nicht auf die E-Mails geantwortet.\",\n            \"Er hat noch nicht auf die E-Mails geantwortet.\"\n          ],\n          \"fragments\": [\n            \"auf seine E-Mails geantwortet\",\n            \"auf die E-Mails geantwortet\",\n            \"E-Mails\",\n            \"noch nicht auf seine E-Mails geantwortet\"\n          ]\n        },\n        {\n          \"id\": \"reading-4\",\n          \"title\": \"Aufgabe 4 – Textverständnis\",\n          \"type\": \"short_answer\",\n          \"prompt\": \"Was gibt es nicht mehr? Antworte in einem ganzen Satz.\",\n          \"hints\": [\n            \"Suche nach der Struktur „kein … mehr“.\",\n            \"Es geht um ein Getränk.\"\n          ],\n          \"feedback\": \"Richtig verstanden und in einem ganzen Satz geantwortet.\",\n          \"examples\": [\n            {\n              \"prompt\": \"„Es gibt kein Wasser mehr.“\"\n            }\n          ],\n          \"accepted\": [\n            \"Es gibt keinen Kaffee mehr.\",\n            \"Im Büro gibt es keinen Kaffee mehr.\"\n          ],\n          \"fragments\": [\n            \"Kaffee\",\n            \"keinen Kaffee\",\n            \"keinen Kaffee mehr\"\n          ]\n        },\n        {\n          \"id\": \"40\",\n          \"title\": \"Aufgabe 5 – Sätze umformen\",\n          \"type\": \"sentence_transform\",\n          \"prompt\": \"Leon ist am Abend gestresst. Verwende: nicht mehr\",\n          \"hints\": [\n            \"Setze den vorgegebenen Negationsausdruck direkt vor den Teil, den du verneinen möchtest.\",\n            \"Achte besonders auf die Stellung von nicht bzw. nicht mehr.\"\n          ],\n          \"feedback\": \"Diese geführte Version ersetzt die sehr offene Originalaufgabe und kann vollständig automatisch geprüft werden.\",\n          \"examples\": [\n            {\n              \"prompt\": \"„Der Bus ist pünktlich.“ + nicht → „Der Bus ist nicht pünktlich.“\"\n            }\n          ],\n          \"accepted\": [\n            \"Leon ist am Abend nicht mehr gestresst.\"\n          ],\n          \"group\": \"reading-transform\"\n        },\n        {\n          \"id\": \"41\",\n          \"title\": \"Aufgabe 5 – Sätze umformen\",\n          \"type\": \"sentence_transform\",\n          \"prompt\": \"Leon geht am Abend ins Fitnessstudio. Verwende: nicht\",\n          \"hints\": [\n            \"Setze den vorgegebenen Negationsausdruck direkt vor den Teil, den du verneinen möchtest.\",\n            \"Achte besonders auf die Stellung von nicht bzw. nicht mehr.\"\n          ],\n          \"feedback\": \"Diese geführte Version ersetzt die sehr offene Originalaufgabe und kann vollständig automatisch geprüft werden.\",\n          \"examples\": [\n            {\n              \"prompt\": \"„Der Bus ist pünktlich.“ + nicht → „Der Bus ist nicht pünktlich.“\"\n            }\n          ],\n          \"accepted\": [\n            \"Leon geht am Abend nicht ins Fitnessstudio.\"\n          ],\n          \"group\": \"reading-transform\"\n        }\n      ],\n      \"examples\": []\n    }\n  ],\n  \"passage\": \"Heute läuft bei Leon nicht alles gut. Am Morgen hat er keine Zeit für Frühstück. Der Bus kommt nicht pünktlich, deshalb erreicht er die Arbeit zu spät. Im Büro findet er niemanden an seinem Platz, denn alle sind in einer Besprechung. Leon hat noch nicht auf seine E-Mails geantwortet und es gibt keinen Kaffee mehr. Mittags möchte er weder Pizza noch Pasta essen. Am Abend ist er aber nicht mehr gestresst: Er geht nicht ins Fitnessstudio, sondern direkt nach Hause und macht einfach nichts.\",\n  \"passageImage\": \"/img/homework/kein-perfekter-montag.webp\"\n}\n','grammar',NULL,NULL,1,NULL,NULL,'2026-10-02 21:34:06','2026-10-21 21:19:00','{\"version\":1,\"key\":\"kapitel-09-negation\",\"title\":\"Kapitel 09 — Negation\",\"label\":\"Kapitel 09\",\"sections\":[{\"id\":\"exercise-1\",\"label\":\"Übung 1\",\"title\":\"Übung 1 – nicht oder kein?\",\"instruction\":\"Ergänze die richtige Negation in passender Form.\",\"examples\":[{\"prompt\":\"Ich habe ___ Fahrrad.\",\"answer\":\"Ich habe kein Fahrrad.\",\"explanation\":\"Nomen: Fahrrad → kein.\"},{\"prompt\":\"Das Fahrrad ist ___ teuer.\",\"answer\":\"Das Fahrrad ist nicht teuer.\",\"explanation\":\"Adjektiv: teuer → nicht.\"}],\"questions\":[{\"id\":\"1\",\"type\":\"fill_blank\",\"prompt\":\"Ich habe ___ Auto.\",\"accepted\":[\"kein\"],\"hints\":[\"Schau auf das Wort nach der Lücke: Ist es ein Nomen?\",\"Auto ist Neutrum und steht hier im Akkusativ.\"],\"feedback\":\"Richtig: kein Auto.\"},{\"id\":\"2\",\"type\":\"fill_blank\",\"prompt\":\"Das Auto ist ___ neu.\",\"accepted\":[\"nicht\"],\"hints\":[\"Was wird verneint: ein Nomen oder die Eigenschaft „neu“?\",\"Adjektive werden normalerweise mit nicht verneint.\"],\"feedback\":\"Richtig: nicht neu.\"},{\"id\":\"3\",\"type\":\"fill_blank\",\"prompt\":\"Wir trinken ___ Kaffee.\",\"accepted\":[\"keinen\"],\"hints\":[\"Kaffee ist ein Nomen.\",\"Kaffee ist maskulin und steht im Akkusativ.\"],\"feedback\":\"Richtig: keinen Kaffee.\"},{\"id\":\"4\",\"type\":\"fill_blank\",\"prompt\":\"Sie kommt heute ___.\",\"accepted\":[\"nicht\"],\"hints\":[\"Hier wird die Handlung „kommen“ verneint.\",\"Für die Verneinung der Handlung verwendest du nicht.\"],\"feedback\":\"Richtig: Sie kommt heute nicht.\"},{\"id\":\"5\",\"type\":\"fill_blank\",\"prompt\":\"Das ist ___ mein Buch.\",\"accepted\":[\"nicht\"],\"hints\":[\"Vor „mein Buch“ steht schon ein Possessivartikel.\",\"Mit Possessivartikeln verwendest du hier nicht.\"],\"feedback\":\"Richtig: Das ist nicht mein Buch.\"},{\"id\":\"6\",\"type\":\"fill_blank\",\"prompt\":\"Er hat ___ Zeit.\",\"accepted\":[\"keine\"],\"hints\":[\"Zeit ist ein Nomen.\",\"Zeit ist feminin.\"],\"feedback\":\"Richtig: keine Zeit.\"},{\"id\":\"7\",\"type\":\"fill_blank\",\"prompt\":\"Ich kenne dort ___ Mann.\",\"accepted\":[\"keinen\"],\"hints\":[\"Mann ist ein Nomen.\",\"Mann ist maskulin und steht im Akkusativ.\"],\"feedback\":\"Richtig: keinen Mann. Diese Formulierung wurde gegenüber der Vorlage bewusst eindeutig gemacht.\"},{\"id\":\"8\",\"type\":\"fill_blank\",\"prompt\":\"Wir fahren ___ mit dem Auto.\",\"accepted\":[\"nicht\"],\"hints\":[\"Hier wird die Handlung bzw. Art des Fahrens verneint.\",\"Setze nicht vor die Präpositionalgruppe.\"],\"feedback\":\"Richtig: Wir fahren nicht mit dem Auto.\"}],\"objective\":\"nicht vs. kein/keine/keinen erkennen und die passende Form einsetzen.\"},{\"id\":\"exercise-2\",\"label\":\"Übung 2\",\"title\":\"Übung 2 – kein deklinieren\",\"instruction\":\"Setze die richtige Form von kein ein.\",\"examples\":[{\"prompt\":\"Ich sehe ___ Hund. (Akk., m.)\",\"answer\":\"Ich sehe keinen Hund.\",\"explanation\":\"Akkusativ + maskulin → keinen.\"},{\"prompt\":\"Sie spricht mit ___ Freundin. (Dat., f.)\",\"answer\":\"Sie spricht mit keiner Freundin.\",\"explanation\":\"Dativ + feminin → keiner.\"}],\"questions\":[{\"id\":\"9\",\"type\":\"fill_blank\",\"prompt\":\"Ich habe ___ Termin. (Akk., m.)\",\"accepted\":[\"keinen\"],\"hints\":[\"Bestimme zuerst Kasus und Genus.\",\"Akkusativ + maskulin hat die Endung -en.\"],\"feedback\":\"Richtig: keinen Termin.\"},{\"id\":\"10\",\"type\":\"fill_blank\",\"prompt\":\"Sie hat ___ Tasche. (Akk., f.)\",\"accepted\":[\"keine\"],\"hints\":[\"Tasche ist feminin.\",\"Akkusativ feminin → keine.\"],\"feedback\":\"Richtig: keine Tasche.\"},{\"id\":\"11\",\"type\":\"fill_blank\",\"prompt\":\"Wir helfen ___ Kunden. (Dat., m.)\",\"accepted\":[\"keinem\"],\"hints\":[\"Das Verb helfen verlangt Dativ.\",\"Dativ maskulin → keinem.\"],\"feedback\":\"Richtig: keinem Kunden.\"},{\"id\":\"12\",\"type\":\"fill_blank\",\"prompt\":\"Er spricht mit ___ Kolleginnen. (Dat., Pl.)\",\"accepted\":[\"keinen\"],\"hints\":[\"Die Präposition mit verlangt Dativ.\",\"Dativ Plural → keinen; das Nomen trägt hier bereits die Pluralform.\"],\"feedback\":\"Richtig: mit keinen Kolleginnen.\"},{\"id\":\"13\",\"type\":\"fill_blank\",\"prompt\":\"Das ist ___ Problem. (Nom., n.)\",\"accepted\":[\"kein\"],\"hints\":[\"Problem ist Neutrum.\",\"Nominativ Neutrum → kein.\"],\"feedback\":\"Richtig: kein Problem.\"},{\"id\":\"14\",\"type\":\"fill_blank\",\"prompt\":\"Wegen ___ Fehlers wurde der Termin verschoben. (Gen., m.; formell)\",\"accepted\":[\"keines\"],\"hints\":[\"Wegen kann formell mit Genitiv stehen.\",\"Genitiv maskulin → keines.\"],\"feedback\":\"Richtig: wegen keines Fehlers.\"}],\"objective\":\"kein nach Kasus, Genus und Numerus korrekt deklinieren.\"},{\"id\":\"exercise-3\",\"label\":\"Übung 3\",\"title\":\"Übung 3 – Stellung von nicht\",\"instruction\":\"Setze „nicht“ an die passende Stelle. Die Information in Klammern soll verneint werden.\",\"examples\":[{\"prompt\":\"Ich fahre heute mit dem Bus. (mit dem Bus)\",\"answer\":\"Ich fahre heute nicht mit dem Bus.\",\"explanation\":\"nicht steht direkt vor dem verneinten Satzteil.\"},{\"prompt\":\"Das Zimmer ist sehr groß. (groß)\",\"answer\":\"Das Zimmer ist nicht sehr groß.\",\"explanation\":\"Bei Adjektiven steht nicht vor der Adjektivgruppe.\"}],\"questions\":[{\"id\":\"15\",\"type\":\"insert_word\",\"prompt\":\"Ich fahre morgen mit dem Auto. (mit dem Auto)\",\"accepted\":[\"Ich fahre morgen nicht mit dem Auto.\"],\"hints\":[\"Welcher Satzteil soll verneint werden?\",\"Setze nicht direkt vor „mit dem Auto“.\"],\"feedback\":\"Richtig: Ich fahre morgen nicht mit dem Auto.\",\"tokens\":[\"Ich\",\"fahre\",\"morgen\",\"mit\",\"dem\",\"Auto.\"],\"word\":\"nicht\",\"positions\":[3]},{\"id\":\"16\",\"type\":\"insert_word\",\"prompt\":\"Wir treffen uns am Montag. (am Montag)\",\"accepted\":[\"Wir treffen uns nicht am Montag.\"],\"hints\":[\"Der Zeitpunkt soll verneint werden.\",\"Setze nicht direkt vor „am Montag“.\"],\"feedback\":\"Richtig: Wir treffen uns nicht am Montag.\",\"tokens\":[\"Wir\",\"treffen\",\"uns\",\"am\",\"Montag.\"],\"word\":\"nicht\",\"positions\":[3]},{\"id\":\"17\",\"type\":\"insert_word\",\"prompt\":\"Anna kommt heute. (Anna – Kontrast: nicht Anna, sondern jemand anderes)\",\"accepted\":[\"Nicht Anna kommt heute.\"],\"hints\":[\"Hier wird ausdrücklich die Person kontrastiert.\",\"Bei Fokusnegation kann nicht direkt vor dem Namen stehen.\"],\"feedback\":\"Richtig als Kontrastfokus: Nicht Anna kommt heute. Die UI soll den Zusatz „sondern jemand anderes“ als Erklärung anzeigen.\",\"tokens\":[\"Anna\",\"kommt\",\"heute.\"],\"word\":\"nicht\",\"positions\":[0]},{\"id\":\"18\",\"type\":\"insert_word\",\"prompt\":\"Das Essen ist sehr teuer. (teuer)\",\"accepted\":[\"Das Essen ist nicht sehr teuer.\"],\"hints\":[\"Die Eigenschaft wird verneint.\",\"Setze nicht vor die Adjektivgruppe „sehr teuer“.\"],\"feedback\":\"Richtig: Das Essen ist nicht sehr teuer.\",\"tokens\":[\"Das\",\"Essen\",\"ist\",\"sehr\",\"teuer.\"],\"word\":\"nicht\",\"positions\":[3]},{\"id\":\"19\",\"type\":\"insert_word\",\"prompt\":\"Er kann morgen kommen. (kommen / ganze Handlung)\",\"accepted\":[\"Er kann morgen nicht kommen.\"],\"hints\":[\"Bei Modalverb + Infinitiv steht nicht oft vor dem Infinitiv.\",\"Setze nicht vor „kommen“.\"],\"feedback\":\"Richtig: Er kann morgen nicht kommen.\",\"tokens\":[\"Er\",\"kann\",\"morgen\",\"kommen.\"],\"word\":\"nicht\",\"positions\":[3]}],\"objective\":\"nicht abhängig vom verneinten Satzteil an die natürliche Position setzen.\"},{\"id\":\"exercise-4\",\"label\":\"Übung 4\",\"title\":\"Übung 4 – nichts, niemand, nie oder nirgendwo\",\"instruction\":\"Ergänze das passende Wort.\",\"examples\":[{\"prompt\":\"Ich esse ___.\",\"answer\":\"Ich esse nichts.\",\"explanation\":\"Sache/Objekt → nichts.\"},{\"prompt\":\"___ wartet vor der Tür.\",\"answer\":\"Niemand wartet vor der Tür.\",\"explanation\":\"Person → niemand.\"}],\"questions\":[{\"id\":\"20\",\"type\":\"fill_blank_adaptive\",\"prompt\":\"Ich sehe ___.\",\"accepted\":[\"nichts\"],\"hints\":[\"Geht es um eine Person, Sache, Zeit oder einen Ort?\",\"Hier geht es um eine Sache/etwas.\"],\"feedback\":\"Richtig: nichts.\",\"wordBank\":[\"nichts\",\"niemand\",\"nie\",\"nirgendwo\"]},{\"id\":\"21\",\"type\":\"fill_blank_adaptive\",\"prompt\":\"___ ist im Büro.\",\"accepted\":[\"niemand\"],\"hints\":[\"Gesucht ist eine Person.\",\"Am Satzanfang wird das Wort großgeschrieben.\"],\"feedback\":\"Richtig: Niemand.\",\"wordBank\":[\"nichts\",\"niemand\",\"nie\",\"nirgendwo\"]},{\"id\":\"22\",\"type\":\"fill_blank_adaptive\",\"prompt\":\"Ich rauche ___.\",\"accepted\":[\"nie\"],\"hints\":[\"Gesucht ist ein Ausdruck für „zu keiner Zeit“.\",\"Zeit/Häufigkeit → nie.\"],\"feedback\":\"Richtig: nie.\",\"wordBank\":[\"nichts\",\"niemand\",\"nie\",\"nirgendwo\"]},{\"id\":\"23\",\"type\":\"fill_blank_adaptive\",\"prompt\":\"Ich finde meinen Schlüssel ___.\",\"accepted\":[\"nirgendwo\"],\"hints\":[\"Gesucht ist ein Ort.\",\"Ort → nirgendwo.\"],\"feedback\":\"Richtig: nirgendwo.\",\"wordBank\":[\"nichts\",\"niemand\",\"nie\",\"nirgendwo\"]},{\"id\":\"24\",\"type\":\"fill_blank_adaptive\",\"prompt\":\"Ich kenne hier ___.\",\"accepted\":[\"niemanden\"],\"hints\":[\"Gesucht ist eine Person im Akkusativ.\",\"niemand bekommt hier die Akkusativendung -en.\"],\"feedback\":\"Richtig: niemanden.\",\"wordBank\":[\"nichts\",\"niemand\",\"nie\",\"nirgendwo\"]},{\"id\":\"25\",\"type\":\"fill_blank_adaptive\",\"prompt\":\"Es gibt ___ Neues.\",\"accepted\":[\"nichts\"],\"hints\":[\"Gesucht ist „keine Sache / nichts“.\",\"Nach nichts kann ein substantiviertes Adjektiv stehen: nichts Neues.\"],\"feedback\":\"Richtig: nichts Neues.\",\"wordBank\":[\"nichts\",\"niemand\",\"nie\",\"nirgendwo\"]}],\"objective\":\"Negativpronomen und Adverbien nach Bedeutung unterscheiden.\"},{\"id\":\"exercise-5\",\"label\":\"Übung 5\",\"title\":\"Übung 5 – noch nicht / nicht mehr / noch nie\",\"instruction\":\"Ergänze den passenden Ausdruck.\",\"examples\":[{\"prompt\":\"Ich habe die Hausaufgaben ___ gemacht; ich mache sie später.\",\"answer\":\"noch nicht\",\"explanation\":\"Bis jetzt nicht, aber später wahrscheinlich → noch nicht.\"},{\"prompt\":\"Früher spielte er Fußball; heute spielt er ___.\",\"answer\":\"nicht mehr\",\"explanation\":\"Früher ja, jetzt nein → nicht mehr.\"}],\"questions\":[{\"id\":\"26\",\"type\":\"phrase_fill\",\"prompt\":\"Ich habe ___ gegessen; ich esse später.\",\"accepted\":[\"noch nicht\"],\"hints\":[\"Ist die Handlung bis jetzt nicht passiert, kann aber später passieren?\",\"Dann verwendest du noch nicht.\"],\"feedback\":\"Richtig: noch nicht.\"},{\"id\":\"27\",\"type\":\"phrase_fill\",\"prompt\":\"Früher wohnte ich hier, aber jetzt wohne ich hier ___.\",\"accepted\":[\"nicht mehr\"],\"hints\":[\"Früher ja, jetzt nein.\",\"Dieser Wechsel wird mit nicht mehr ausgedrückt.\"],\"feedback\":\"Richtig: nicht mehr.\"},{\"id\":\"28\",\"type\":\"phrase_fill\",\"prompt\":\"Ich war ___ in Österreich.\",\"accepted\":[\"noch nie\",\"nie\"],\"hints\":[\"Geht es um eine Erfahrung bis zum heutigen Zeitpunkt?\",\"noch nie betont „bis jetzt“. Auch nie ist grammatisch korrekt.\"],\"feedback\":\"Bevorzugt: noch nie. Akzeptiert wird auch: nie.\"},{\"id\":\"29\",\"type\":\"phrase_fill\",\"prompt\":\"Der Kurs ist ___ zu Ende.\",\"accepted\":[\"noch nicht\"],\"hints\":[\"Der Kurs läuft im Moment weiter.\",\"Bis jetzt nicht beendet → noch nicht.\"],\"feedback\":\"Richtig: noch nicht.\"},{\"id\":\"30\",\"type\":\"phrase_fill\",\"prompt\":\"Wir haben ___ Kaffee ___; alles ist aufgebraucht.\",\"accepted\":[[\"keinen\",\"mehr\"]],\"hints\":[\"Hier brauchst du zwei Teile.\",\"Vor Kaffee steht die Form von kein; nach Kaffee steht mehr.\"],\"feedback\":\"Richtig: keinen Kaffee mehr.\"}],\"objective\":\"zeitliche Negationsausdrücke nach Bedeutung unterscheiden.\"},{\"id\":\"exercise-6\",\"label\":\"Übung 6\",\"title\":\"Übung 6 – weder … noch / sondern\",\"instruction\":\"Verbinde die Aussagen. Schreibe zuerst selbst; bei Schwierigkeiten erhältst du schrittweise Hilfe.\",\"examples\":[{\"prompt\":\"Ich esse kein Fleisch. Ich esse keinen Fisch.\",\"answer\":\"Ich esse weder Fleisch noch Fisch.\",\"explanation\":\"Zwei negative Alternativen → weder … noch.\"},{\"prompt\":\"Sie fährt nicht heute. Sie fährt morgen.\",\"answer\":\"Sie fährt nicht heute, sondern morgen.\",\"explanation\":\"Korrektur/Kontrast → sondern.\"}],\"questions\":[{\"id\":\"31\",\"type\":\"sentence_transform_adaptive\",\"prompt\":\"Ich trinke keinen Kaffee. Ich trinke keinen Tee.\",\"accepted\":[\"Ich trinke weder Kaffee noch Tee.\",\"Weder Kaffee noch Tee trinke ich.\"],\"hints\":[\"Sind beide Möglichkeiten negativ?\",\"Verwende weder vor Kaffee und noch vor Tee.\"],\"feedback\":\"Richtig: Ich trinke weder Kaffee noch Tee.\",\"skeleton\":\"Ich trinke ___ Kaffee ___ Tee.\",\"builderWords\":[\"weder\",\"noch\",\"sondern\"]},{\"id\":\"32\",\"type\":\"sentence_transform_adaptive\",\"prompt\":\"Er kommt nicht heute. Er kommt morgen.\",\"accepted\":[\"Er kommt nicht heute, sondern morgen.\",\"Er kommt heute nicht, sondern morgen.\"],\"hints\":[\"Die zweite Aussage korrigiert die erste.\",\"Verbinde mit sondern.\"],\"feedback\":\"Richtig: Er kommt heute nicht, sondern morgen.\",\"skeleton\":\"Er kommt nicht heute, ___ morgen.\",\"builderWords\":[\"weder\",\"noch\",\"sondern\"]},{\"id\":\"33\",\"type\":\"sentence_transform_adaptive\",\"prompt\":\"Das ist kein Hotel. Das ist ein Büro.\",\"accepted\":[\"Das ist kein Hotel, sondern ein Büro.\"],\"hints\":[\"Die zweite Aussage stellt richtig, was es ist.\",\"Nach der negativen Aussage passt sondern.\"],\"feedback\":\"Richtig: Das ist kein Hotel, sondern ein Büro.\",\"skeleton\":\"Das ist kein Hotel, ___ ein Büro.\",\"builderWords\":[\"weder\",\"noch\",\"sondern\"]},{\"id\":\"34\",\"type\":\"sentence_transform_adaptive\",\"prompt\":\"Sie spricht nicht Französisch. Sie spricht nicht Spanisch.\",\"accepted\":[\"Sie spricht weder Französisch noch Spanisch.\",\"Weder Französisch noch Spanisch spricht sie.\"],\"hints\":[\"Beide Sprachen werden ausgeschlossen.\",\"Verwende weder … noch.\"],\"feedback\":\"Richtig: Sie spricht weder Französisch noch Spanisch.\",\"skeleton\":\"Sie spricht ___ Französisch ___ Spanisch.\",\"builderWords\":[\"weder\",\"noch\",\"sondern\"]}],\"objective\":\"zwei Aussagen mit weder … noch oder sondern korrekt verbinden.\"},{\"id\":\"exercise-7\",\"label\":\"Übung 7\",\"title\":\"Übung 7 – Fehler korrigieren\",\"instruction\":\"Korrigiere den Satz. Bearbeite möglichst nur die Stelle, die falsch ist.\",\"examples\":[{\"prompt\":\"Ich habe nicht Auto.\",\"answer\":\"Ich habe kein Auto.\",\"explanation\":\"Nomen ohne bestimmten Artikel → kein.\"},{\"prompt\":\"Das Wetter ist kein schön.\",\"answer\":\"Das Wetter ist nicht schön.\",\"explanation\":\"Adjektiv → nicht.\"}],\"questions\":[{\"id\":\"35\",\"type\":\"sentence_correction\",\"prompt\":\"Ich habe nicht Geld.\",\"accepted\":[\"Ich habe kein Geld.\"],\"hints\":[\"Was wird verneint: ein Nomen oder eine Eigenschaft?\",\"Geld ist ein Nomen.\"],\"feedback\":\"Richtig: Ich habe kein Geld.\"},{\"id\":\"36\",\"type\":\"sentence_correction\",\"prompt\":\"Niemand kommt nicht.\",\"accepted\":[\"Niemand kommt.\"],\"hints\":[\"Achte auf doppelte Negation.\",\"Niemand enthält die Negation schon.\"],\"feedback\":\"Richtig: Niemand kommt.\"},{\"id\":\"37\",\"type\":\"sentence_correction\",\"prompt\":\"Das ist kein interessant.\",\"accepted\":[\"Das ist nicht interessant.\"],\"hints\":[\"interessant ist ein Adjektiv.\",\"Adjektiv → nicht.\"],\"feedback\":\"Richtig: Das ist nicht interessant.\"},{\"id\":\"38\",\"type\":\"sentence_correction\",\"prompt\":\"Ich war nicht nie in Berlin.\",\"accepted\":[\"Ich war noch nie in Berlin.\",\"Ich war nie in Berlin.\"],\"hints\":[\"Hier stehen zwei Negationen unnötig zusammen.\",\"Verwende nie oder – für „bis jetzt“ – noch nie.\"],\"feedback\":\"Bevorzugt: Ich war noch nie in Berlin. Akzeptiert: Ich war nie in Berlin.\"},{\"id\":\"39\",\"type\":\"sentence_correction\",\"prompt\":\"Wir haben nicht Milch mehr.\",\"accepted\":[\"Wir haben keine Milch mehr.\"],\"hints\":[\"Milch ist ein Nomen.\",\"Feminin: keine; mehr steht nach dem Nomen.\"],\"feedback\":\"Richtig: Wir haben keine Milch mehr.\"}],\"objective\":\"typische Fehler bei der Negation erkennen und selbst korrigieren.\"},{\"id\":\"reading\",\"label\":\"Lesetext\",\"title\":\"Lesetext — Kein perfekter Montag\",\"instruction\":\"Lies den Text und bearbeite die Aufgaben.\",\"questions\":[{\"id\":\"reading-1\",\"title\":\"Aufgabe 1 – Markieren\",\"type\":\"text_highlight\",\"prompt\":\"Markiere alle Negations- und Kontrastausdrücke im Text.\",\"hints\":[\"Suche nach nicht, Formen von kein, Negativpronomen und Konnektoren.\",\"Es gibt 11 zu markierende Ausdrücke, wenn mehrteilige Ausdrücke als Einheit gezählt werden.\"],\"feedback\":\"Die Markierungen werden direkt im Text geprüft; mehrteilige Ausdrücke werden als zusammengehörige Gruppe gespeichert.\",\"examples\":[{\"prompt\":\"„Der Bus ist nicht pünktlich.“ → Markiere „nicht“.\"}],\"tokens\":[\"Heute\",\"läuft\",\"bei\",\"Leon\",\"nicht\",\"alles\",\"gut.\",\"Am\",\"Morgen\",\"hat\",\"er\",\"keine\",\"Zeit\",\"für\",\"Frühstück.\",\"Der\",\"Bus\",\"kommt\",\"nicht\",\"pünktlich,\",\"deshalb\",\"erreicht\",\"er\",\"die\",\"Arbeit\",\"zu\",\"spät.\",\"Im\",\"Büro\",\"findet\",\"er\",\"niemanden\",\"an\",\"seinem\",\"Platz,\",\"denn\",\"alle\",\"sind\",\"in\",\"einer\",\"Besprechung.\",\"Leon\",\"hat\",\"noch\",\"nicht\",\"auf\",\"seine\",\"E-Mails\",\"geantwortet\",\"und\",\"es\",\"gibt\",\"keinen\",\"Kaffee\",\"mehr.\",\"Mittags\",\"möchte\",\"er\",\"weder\",\"Pizza\",\"noch\",\"Pasta\",\"essen.\",\"Am\",\"Abend\",\"ist\",\"er\",\"aber\",\"nicht\",\"mehr\",\"gestresst:\",\"Er\",\"geht\",\"nicht\",\"ins\",\"Fitnessstudio,\",\"sondern\",\"direkt\",\"nach\",\"Hause\",\"und\",\"macht\",\"einfach\",\"nichts.\"],\"groups\":[{\"id\":\"expression-1\",\"label\":\"nicht (nicht alles)\",\"category\":\"nicht\",\"tokens\":[4]},{\"id\":\"expression-2\",\"label\":\"keine\",\"category\":\"kein\",\"tokens\":[11]},{\"id\":\"expression-3\",\"label\":\"nicht (nicht pünktlich)\",\"category\":\"nicht\",\"tokens\":[18]},{\"id\":\"expression-4\",\"label\":\"niemanden\",\"category\":\"Negativpronomen\",\"tokens\":[31]},{\"id\":\"expression-5\",\"label\":\"noch nicht\",\"category\":\"Zeit-/Verlaufs-Ausdruck\",\"tokens\":[43,44]},{\"id\":\"expression-6\",\"label\":\"keinen … mehr\",\"category\":\"kein\",\"tokens\":[52,54]},{\"id\":\"expression-7\",\"label\":\"weder … noch\",\"category\":\"Konnektor\",\"tokens\":[58,60]},{\"id\":\"expression-8\",\"label\":\"nicht mehr\",\"category\":\"Zeit-/Verlaufs-Ausdruck\",\"tokens\":[68,69]},{\"id\":\"expression-9\",\"label\":\"nicht (nicht ins Fitnessstudio)\",\"category\":\"nicht\",\"tokens\":[73]},{\"id\":\"expression-10\",\"label\":\"sondern\",\"category\":\"Konnektor\",\"tokens\":[76]},{\"id\":\"expression-11\",\"label\":\"nichts\",\"category\":\"Negativpronomen\",\"tokens\":[83]}]},{\"id\":\"reading-2\",\"title\":\"Aufgabe 2 – Sortieren\",\"type\":\"categorize\",\"prompt\":\"Ordne die markierten Ausdrücke der passenden Kategorie zu.\",\"hints\":[\"Frage dich: Nomen-Verneinung, Person/Sache, Zeitverlauf oder Verbindung/Kontrast?\",\"weder … noch und sondern gehören zu den Konnektoren.\"],\"feedback\":\"Nach dem Sortieren zeigt die UI pro Kategorie eine kurze Regel.\",\"examples\":[{\"prompt\":\"„niemanden“ → Negativpronomen.\"}],\"items\":[{\"id\":\"expression-1\",\"label\":\"nicht (nicht alles)\",\"category\":\"nicht\"},{\"id\":\"expression-2\",\"label\":\"keine\",\"category\":\"kein\"},{\"id\":\"expression-3\",\"label\":\"nicht (nicht pünktlich)\",\"category\":\"nicht\"},{\"id\":\"expression-4\",\"label\":\"niemanden\",\"category\":\"Negativpronomen\"},{\"id\":\"expression-5\",\"label\":\"noch nicht\",\"category\":\"Zeit-/Verlaufs-Ausdruck\"},{\"id\":\"expression-6\",\"label\":\"keinen … mehr\",\"category\":\"kein\"},{\"id\":\"expression-7\",\"label\":\"weder … noch\",\"category\":\"Konnektor\"},{\"id\":\"expression-8\",\"label\":\"nicht mehr\",\"category\":\"Zeit-/Verlaufs-Ausdruck\"},{\"id\":\"expression-9\",\"label\":\"nicht (nicht ins Fitnessstudio)\",\"category\":\"nicht\"},{\"id\":\"expression-10\",\"label\":\"sondern\",\"category\":\"Konnektor\"},{\"id\":\"expression-11\",\"label\":\"nichts\",\"category\":\"Negativpronomen\"}],\"categories\":[\"nicht\",\"kein\",\"Negativpronomen\",\"Zeit-/Verlaufs-Ausdruck\",\"Konnektor\"],\"rules\":{\"nicht\":\"nicht verneint hier Satzteile oder Handlungen.\",\"kein\":\"kein verneint Nomen mit unbestimmtem oder ohne Artikel.\",\"Negativpronomen\":\"niemanden bezeichnet Personen, nichts bezeichnet Sachen.\",\"Zeit-/Verlaufs-Ausdruck\":\"noch nicht und nicht mehr beschreiben einen zeitlichen Verlauf.\",\"Konnektor\":\"weder … noch schließt beide Alternativen aus; sondern korrigiert eine negative Aussage.\"}},{\"id\":\"reading-3\",\"title\":\"Aufgabe 3 – Textverständnis\",\"type\":\"short_answer\",\"prompt\":\"Was hat Leon noch nicht gemacht? Antworte in einem ganzen Satz.\",\"hints\":[\"Suche im Text nach „noch nicht“.\",\"Die Stelle steht im Satz mit den E-Mails.\"],\"feedback\":\"Richtig verstanden und in einem ganzen Satz geantwortet.\",\"examples\":[{\"prompt\":\"„Er hat noch nicht gefrühstückt.“\"}],\"accepted\":[\"Leon hat noch nicht auf seine E-Mails geantwortet.\",\"Er hat noch nicht auf seine E-Mails geantwortet.\",\"Leon hat noch nicht auf die E-Mails geantwortet.\",\"Er hat noch nicht auf die E-Mails geantwortet.\"],\"fragments\":[\"auf seine E-Mails geantwortet\",\"auf die E-Mails geantwortet\",\"E-Mails\",\"noch nicht auf seine E-Mails geantwortet\"]},{\"id\":\"reading-4\",\"title\":\"Aufgabe 4 – Textverständnis\",\"type\":\"short_answer\",\"prompt\":\"Was gibt es nicht mehr? Antworte in einem ganzen Satz.\",\"hints\":[\"Suche nach der Struktur „kein … mehr“.\",\"Es geht um ein Getränk.\"],\"feedback\":\"Richtig verstanden und in einem ganzen Satz geantwortet.\",\"examples\":[{\"prompt\":\"„Es gibt kein Wasser mehr.“\"}],\"accepted\":[\"Es gibt keinen Kaffee mehr.\",\"Im Büro gibt es keinen Kaffee mehr.\"],\"fragments\":[\"Kaffee\",\"keinen Kaffee\",\"keinen Kaffee mehr\"]},{\"id\":\"40\",\"title\":\"Aufgabe 5 – Sätze umformen\",\"type\":\"sentence_transform\",\"prompt\":\"Leon ist am Abend gestresst. Verwende: nicht mehr\",\"hints\":[\"Setze den vorgegebenen Negationsausdruck direkt vor den Teil, den du verneinen möchtest.\",\"Achte besonders auf die Stellung von nicht bzw. nicht mehr.\"],\"feedback\":\"Diese geführte Version ersetzt die sehr offene Originalaufgabe und kann vollständig automatisch geprüft werden.\",\"examples\":[{\"prompt\":\"„Der Bus ist pünktlich.“ + nicht → „Der Bus ist nicht pünktlich.“\"}],\"accepted\":[\"Leon ist am Abend nicht mehr gestresst.\"],\"group\":\"reading-transform\"},{\"id\":\"41\",\"title\":\"Aufgabe 5 – Sätze umformen\",\"type\":\"sentence_transform\",\"prompt\":\"Leon geht am Abend ins Fitnessstudio. Verwende: nicht\",\"hints\":[\"Setze den vorgegebenen Negationsausdruck direkt vor den Teil, den du verneinen möchtest.\",\"Achte besonders auf die Stellung von nicht bzw. nicht mehr.\"],\"feedback\":\"Diese geführte Version ersetzt die sehr offene Originalaufgabe und kann vollständig automatisch geprüft werden.\",\"examples\":[{\"prompt\":\"„Der Bus ist pünktlich.“ + nicht → „Der Bus ist nicht pünktlich.“\"}],\"accepted\":[\"Leon geht am Abend nicht ins Fitnessstudio.\"],\"group\":\"reading-transform\"}],\"examples\":[]}],\"passage\":\"Heute läuft bei Leon nicht alles gut. Am Morgen hat er keine Zeit für Frühstück. Der Bus kommt nicht pünktlich, deshalb erreicht er die Arbeit zu spät. Im Büro findet er niemanden an seinem Platz, denn alle sind in einer Besprechung. Leon hat noch nicht auf seine E-Mails geantwortet und es gibt keinen Kaffee mehr. Mittags möchte er weder Pizza noch Pasta essen. Am Abend ist er aber nicht mehr gestresst: Er geht nicht ins Fitnessstudio, sondern direkt nach Hause und macht einfach nichts.\",\"passageImage\":\"/img/homework/kein-perfekter-montag.webp\"}','homework',NULL,NULL,NULL,1),
(95,3,NULL,'Die Farben','Lies den Text und beantworte danach die Aufgaben.',NULL,NULL,NULL,'@reading\n{\n  \"templateVersion\": \"1.0\",\n  \"contentVersion\": 1,\n  \"meta\": {\n    \"lessonId\": \"a1-die-farben\",\n    \"slug\": \"a1-die-farben\",\n    \"title\": \"Die Farben\",\n    \"cefrLevel\": \"A1\",\n    \"status\": \"published\",\n    \"estimatedMinutes\": 8,\n    \"sourceReference\": \"3_Farben_A1_source.pdf\"\n  },\n  \"presentation\": {\n    \"instructions\": \"Lies den Text und beantworte danach die Aufgaben.\",\n    \"coverImage\": null\n  },\n  \"reading\": {\n    \"language\": \"de\",\n    \"contentBlocks\": [\n      {\n        \"id\": \"p1\",\n        \"type\": \"paragraph\",\n        \"text\": \"Farben machen das Leben bunt. Der Regenbogen besteht aus vielen Farben. Obst und Gemüse ist oft sehr farbig. Und unsere Kleidung kann auch schön bunt sein. Eine starke Farbe ist rot. Viele Früchte sind rot, zum Beispiel Erdbeeren oder Himbeeren. Es gibt auch rotes Gemüse: Tomaten. Viele Blumen sind rot, zum Beispiel Rosen. Gelb wie die Sonne sind auch Bananen, Zitronen oder Mais. Blau ist der Himmel bei schönem Wetter oder auch das Meer oder ein See. Es gibt viele verschiedene Arten von blau: helles blau oder dunkles blau, türkis oder himmelblau.\"\n      },\n      {\n        \"id\": \"p2\",\n        \"type\": \"paragraph\",\n        \"text\": \"Alle Farben zusammen ergeben schwarz. Schwarz ist die Nacht. Das Gegenteil von schwarz ist weiß. Es gibt weiße Blumen, die Wolken sind weiß. Oder der Schnee. Sehr viel in der Natur ist grün: Blätter, Gras und Bäume. Die Stämme der Bäume sind meistens braun. Oder auch Kaffee oder gebackenes Brot.\"\n      },\n      {\n        \"id\": \"p3\",\n        \"type\": \"paragraph\",\n        \"text\": \"Es gibt noch sehr viele Farben: Grau sind zum Beispiel Tauben, orange ist der Himmel bei einem Sonnenuntergang. Eine starke Farbe ist pink: sie fällt auf. In der Natur gibt es pinke Blumen oder auch Vögel. Lila ist ähnlich, viele Blumen sind lila oder rosarot. Die edlen Farben sind golden und Silber: Wir finden sie bei Edelsteinen und Schmuck.\"\n      }\n    ],\n    \"dictionaryInteraction\": {\n      \"enabled\": true,\n      \"maxSelectionCharacters\": 250\n    }\n  },\n  \"exerciseSettings\": {\n    \"feedbackMode\": \"immediate\",\n    \"allowRetry\": true,\n    \"allowHint\": true,\n    \"revealSupportAfterAttempts\": 2\n  },\n  \"exercises\": [\n    {\n      \"id\": \"q1\",\n      \"position\": 1,\n      \"type\": \"multiple_choice\",\n      \"prompt\": \"Welche Dinge sind nicht rot?\",\n      \"required\": true,\n      \"options\": [\n        {\n          \"id\": \"a\",\n          \"text\": \"Bananen\"\n        },\n        {\n          \"id\": \"b\",\n          \"text\": \"Tomaten\"\n        },\n        {\n          \"id\": \"c\",\n          \"text\": \"Erdbeeren\"\n        },\n        {\n          \"id\": \"d\",\n          \"text\": \"Rosen\"\n        }\n      ],\n      \"answerKey\": {\n        \"correctOptionIds\": [\n          \"a\"\n        ]\n      },\n      \"feedback\": {\n        \"correct\": \"Richtig!\",\n        \"incorrect\": \"Noch nicht richtig. Lies die passende Stelle im Text noch einmal.\",\n        \"explanation\": \"Gelb wie die Sonne sind auch Bananen, Zitronen oder Mais.\"\n      },\n      \"hints\": [\n        \"Lies im ersten Absatz noch einmal die Beispiele für Rot und Gelb.\"\n      ],\n      \"support\": {\n        \"blockId\": \"p1\",\n        \"anchorText\": \"Gelb wie die Sonne sind auch Bananen, Zitronen oder Mais.\"\n      }\n    },\n    {\n      \"id\": \"q2\",\n      \"position\": 2,\n      \"type\": \"multiple_choice\",\n      \"prompt\": \"Was gehört nicht zu blau?\",\n      \"required\": true,\n      \"options\": [\n        {\n          \"id\": \"a\",\n          \"text\": \"türkis\"\n        },\n        {\n          \"id\": \"b\",\n          \"text\": \"himmelblau\"\n        },\n        {\n          \"id\": \"c\",\n          \"text\": \"schwarz\"\n        },\n        {\n          \"id\": \"d\",\n          \"text\": \"dunkelblau\"\n        }\n      ],\n      \"answerKey\": {\n        \"correctOptionIds\": [\n          \"c\"\n        ]\n      },\n      \"feedback\": {\n        \"correct\": \"Richtig!\",\n        \"incorrect\": \"Noch nicht richtig. Lies die passende Stelle im Text noch einmal.\",\n        \"explanation\": \"Es gibt viele verschiedene Arten von blau: helles blau oder dunkles blau, türkis oder himmelblau.\"\n      },\n      \"hints\": [\n        \"Suche die Stelle mit verschiedenen Arten von Blau.\"\n      ],\n      \"support\": {\n        \"blockId\": \"p1\",\n        \"anchorText\": \"Es gibt viele verschiedene Arten von blau: helles blau oder dunkles blau, türkis oder himmelblau.\"\n      }\n    },\n    {\n      \"id\": \"q3\",\n      \"position\": 3,\n      \"type\": \"multiple_choice\",\n      \"prompt\": \"Was ist weiß?\",\n      \"required\": true,\n      \"options\": [\n        {\n          \"id\": \"a\",\n          \"text\": \"Blätter und Gräser\"\n        },\n        {\n          \"id\": \"b\",\n          \"text\": \"Tauben und Schmuck\"\n        },\n        {\n          \"id\": \"c\",\n          \"text\": \"Schnee und Wolken\"\n        },\n        {\n          \"id\": \"d\",\n          \"text\": \"Kaffee und Mais\"\n        }\n      ],\n      \"answerKey\": {\n        \"correctOptionIds\": [\n          \"c\"\n        ]\n      },\n      \"feedback\": {\n        \"correct\": \"Richtig!\",\n        \"incorrect\": \"Noch nicht richtig. Lies die passende Stelle im Text noch einmal.\",\n        \"explanation\": \"Es gibt weiße Blumen, die Wolken sind weiß. Oder der Schnee.\"\n      },\n      \"hints\": [\n        \"Lies im zweiten Absatz nach dem Wort „weiß“.\"\n      ],\n      \"support\": {\n        \"blockId\": \"p2\",\n        \"anchorText\": \"Es gibt weiße Blumen, die Wolken sind weiß. Oder der Schnee.\"\n      }\n    },\n    {\n      \"id\": \"q4\",\n      \"position\": 4,\n   