DROP TABLE IF EXISTS `intakes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `intakes` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `course_id` int(10) unsigned NOT NULL,
  `code` varchar(40) NOT NULL,
  `title` varchar(200) DEFAULT NULL,
  `teacher_id` int(10) unsigned DEFAULT NULL,
  `teacher_name` varchar(120) DEFAULT NULL,
  `teacher2_id` int(10) unsigned DEFAULT NULL,
  `teacher2_name` varchar(120) DEFAULT NULL,
  `starts_on` date DEFAULT NULL,
  `ends_on` date DEFAULT NULL,
  `timezone` varchar(64) NOT NULL DEFAULT 'Europe/Berlin',
  `meets_days` varchar(20) DEFAULT NULL,
  `meets_from` time DEFAULT NULL,
  `meets_minutes` smallint(5) unsigned NOT NULL DEFAULT 120,
  `seats` smallint(5) unsigned DEFAULT NULL,
  `meeting_url` varchar(500) DEFAULT NULL,
  `drive_url` varchar(500) DEFAULT NULL,
  `whatsapp_url` varchar(500) DEFAULT NULL,
  `exercise_url` varchar(500) DEFAULT NULL,
  `status` enum('planned','running','finished','cancelled') NOT NULL DEFAULT 'planned',
  `status_auto` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_code` (`code`),
  KEY `idx_course` (`course_id`),
  KEY `idx_teacher` (`teacher_id`),
  KEY `idx_status_start` (`status`,`starts_on`),
  KEY `idx_teacher2` (`teacher2_id`),
  KEY `idx_status_auto` (`status_auto`,`status`),
  CONSTRAINT `fk_intakes_course` FOREIGN KEY (`course_id`) REFERENCES `courses` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_intakes_teacher` FOREIGN KEY (`teacher_id`) REFERENCES `admin_users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_intakes_teacher2` FOREIGN KEY (`teacher2_id`) REFERENCES `admin_users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
