  `level` varchar(4) DEFAULT NULL,
  `title` varchar(200) NOT NULL,
  `description` varchar(400) DEFAULT NULL,
  `stored_name` varchar(160) NOT NULL,
  `original_name` varchar(255) DEFAULT NULL,
  `mime` varchar(100) DEFAULT NULL,
  `bytes` int(10) unsigned DEFAULT NULL,
  `kind` enum('worksheet','audio','video','reading','exam','other') NOT NULL DEFAULT 'other',
  `sort_order` smallint(6) NOT NULL DEFAULT 0,
  `visible` tinyint(1) NOT NULL DEFAULT 1,
  `uploaded_by` int(10) unsigned DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_stored` (`stored_name`),
  KEY `idx_intake` (`intake_id`,`sort_order`),
  KEY `idx_level` (`level`),
  KEY `fk_materials_uploader` (`uploaded_by`),
  CONSTRAINT `fk_materials_intake` FOREIGN KEY (`intake_id`) REFERENCES `intakes` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_materials_uploader` FOREIGN KEY (`uploaded_by`) REFERENCES `admin_users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
